INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('21','BrowserElement.create_element','{"key": "BrowserElement.create_element", "title": "获取元素对象（web）", "version": "1.0.5", "src": "astronverse.browser.browser_element.BrowserElement().create_element", "comment": "在指定的浏览器对象 @{browser_obj} 中根据 @{locate_type}获取元素对象 ，将结果输出为元素对象 @{element_obj}", "inputList": [{"types": "Browser", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "browser_obj", "title": "浏览器对象", "name": "browser_obj", "tip": "", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "LocateType", "formType": {"type": "SELECT"}, "key": "locate_type", "title": "定位方式", "name": "locate_type", "tip": "选择 Xpath/css选择器/文字 定位方式", "options": [{"label": "xpath", "value": "xpath"}, {"label": "css选择器", "value": "cssSelector"}, {"label": "文字", "value": "text"}], "default": "xpath", "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "locate_value", "title": "Xpath/css选择器/文字", "name": "locate_value", "tip": "输入对应定位方式的 Xpath / css选择器 / 文字内容", "default": "", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "ElementCreateReturnType", "formType": {"type": "RADIO"}, "key": "return_type", "title": "返回值类型", "name": "return_type", "tip": "选择返回单个元素对象还是元素对象列表", "options": [{"label": "单个元素对象", "value": "single"}, {"label": "元素对象列表", "value": "list"}], "default": "list", "required": true}], "outputList": [{"types": "Any", "formType": {"type": "RESULT"}, "key": "element_obj", "title": "元素对象", "tip": "输出元素对象，结果为单个对象或列表"}], "icon": "get-element-object-web", "helpManual": ""}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('22','BrowserElement.data_batch','{"key": "BrowserElement.data_batch", "title": "数据抓取（web）", "version": "1.0.5", "src": "astronverse.browser.browser_element.BrowserElement().data_batch", "comment": "在指定的浏览器对象 @{browser_obj} 中抓取 @{batch_data} ，将结果输出为 @{table_pick}", "inputList": [{"types": "Browser", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "browser_obj", "title": "浏览器对象", "name": "browser_obj", "tip": "选择要等待页面所在的浏览器对象", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "WebPick", "formType": {"type": "PICK", "params": {"use": "BATCH"}}, "key": "batch_data", "title": "抓取对象", "name": "batch_data", "tip": "拾取需要抓取的元素", "required": true, "noInput": true}, {"types": "Bool", "formType": {"type": "SWITCH", "params": {}}, "key": "multi_page", "title": "是否抓取多页", "name": "multi_page", "tip": "选择需要是否抓取多页，默认抓取当前页", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": false, "required": false}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "page_count", "title": "抓取页数", "name": "page_count", "tip": "填写需要抓取的总页数，例如：抓取10页，则填写10", "default": 1, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.page_count.show", "expression": "return $this.multi_page.value == true"}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "page_interval", "title": "翻页间隔时间，单位：秒", "name": "page_interval", "tip": "填写翻页的间隔时间，若间隔时间过短导致页面加载不完全，可适当增加翻页间隔时间", "default": 1, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.page_interval.show", "expression": "return $this.multi_page.value == true"}], "required": true}, {"types": "WebPick", "formType": {"type": "PICK", "params": {"use": "WebPick"}}, "key": "element_data", "title": "翻页按钮", "name": "element_data", "tip": "拾取需要翻页的元素", "dynamics": [{"key": "$this.element_data.show", "expression": "r