INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('27','BrowserElement.get_relative_element','{"key": "BrowserElement.get_relative_element", "title": "获取关联元素（web）", "version": "1.0.5", "src": "astronverse.browser.browser_element.BrowserElement().get_relative_element", "comment": "在指定的浏览器对象 @{browser_obj} 中获取 @{element_data} 关联的 @{relative_type}，将结果输出为元素对象 @{element_obj}", "inputList": [{"types": "Browser", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "browser_obj", "title": "浏览器对象", "name": "browser_obj", "tip": "", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "WebPick", "formType": {"type": "PICK", "params": {"use": "WebPick"}}, "key": "element_data", "title": "元素对象", "name": "element_data", "tip": "作为锚点的元素，只能是单个元素对象，不能是列表", "required": true, "noInput": true}, {"types": "RelativeType", "formType": {"type": "SELECT"}, "key": "relative_type", "title": "关联类型", "name": "relative_type", "tip": "选择关联类型，例如：兄弟元素、父级元素、子级元素等", "options": [{"label": "子元素", "value": "child"}, {"label": "父元素", "value": "parent"}, {"label": "兄弟元素", "value": "sibling"}], "default": "child", "required": true}, {"types": "ChildElementType", "formType": {"type": "SELECT"}, "key": "child_element_type", "title": "子元素类型", "name": "child_element_type", "tip": "选择获取子元素的类型", "options": [{"label": "所有子元素", "value": "all"}, {"label": "第n个子元素", "value": "index"}, {"label": "子元素xpath", "value": "xpath"}, {"label": "最后一个子元素", "value": "last"}], "default": "all", "dynamics": [{"key": "$this.child_element_type.show", "expression": "return $this.relative_type.value == ''child''"}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "child_element_xpath", "title": "子元素xpath", "name": "child_element_xpath", "tip": "填写子元素的xpath，仅获取单个元素", "default": "", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.child_element_xpath.show", "expression": "return $this.child_element_type.value == ''xpath'' && $this.relative_type.value == ''child''"}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "child_element_index", "title": "子元素位置", "name": "child_element_index", "tip": "填写子元素位置，例如：0表示第一个子元素", "default": 0, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.child_element_index.show", "expression": "return $this.child_element_type.value == ''index'' && $this.relative_type.value == ''child''"}], "required": true}, {"types": "SiblingElementType", "formType": {"type": "SELECT"}, "key": "sibling_element_type", "title": "兄弟元素类型", "name": "sibling_element_type", "tip": "选择获取兄弟元素的类型", "options": [{"label": "所有兄弟元素", "value": "all"}, {"label": "下一个兄弟元素", "value": "next"}, {"label": "上一个兄弟元素", "value": "prev"}], "default": "all", "dynamics": [{"key": "$this.sibling_element_type.show", "expression": "return $this.relative_type.value == ''sibling''"}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "element_timeout", "title": "等待元素出现时间（秒）", "name": "element_timeout", "tip": "超过该时间停止等待", "default": 10, "value": [{"type": "str", "value": ""}], "required": true}, {"types": "Bool", "formType": {"type": "SWITCH", "params": {}}, "key": "is_multiple", "title": "是否返回多个元素", "name": "is_multiple", "tip": "控制使用xpath获取子元素时返回单个/多个元素", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": false, "dynamics": [{"key": "$this.is_multiple.show", "expression": "return $this.child_element_type.value == ''xpath'' && $this.relative_type.value == ''child''"}], "required": true}], "outputList": [{"types": "Any", "formType": {"type": "RESULT"}, "key": "element_obj", "title": "元素对象", "tip": "输出元素对象，结果为单个对象或列表"}], "icon": "get-related-elements-web", "helpManual": ""}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
