INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('29','BrowserElement.get_table','{"key": "BrowserElement.get_table", "title": "获取表格数据（web）", "version": "1.0.5", "src": "astronverse.browser.browser_element.BrowserElement().get_table", "comment": "获取浏览器对象 @{browser_obj} 中的表格 @{element_data} ，将结果输出为 @{table_pick}", "inputList": [{"types": "Browser", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "browser_obj", "title": "浏览器对象", "name": "browser_obj", "tip": "选择要等待页面所在的浏览器对象", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "WebPick", "formType": {"type": "PICK", "params": {"use": "WebPick"}}, "key": "element_data", "title": "拾取表格", "name": "element_data", "tip": "拾取网页表格中任一单元格元素，无须拾取整个表格", "required": true, "noInput": true}, {"types": "Bool", "formType": {"type": "SWITCH", "params": {}}, "key": "to_excel", "title": "存储到表格文档", "name": "to_excel", "tip": "可直接存储为excel文档", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": false, "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON_FILE", "params": {"file_type": "file"}}, "key": "excel_path", "title": "表格文档路径", "name": "excel_path", "tip": "请选择文档存储路径", "default": "", "dynamics": [{"key": "$this.excel_path.show", "expression": "return $this.to_excel.value == true"}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "element_timeout", "title": "等待元素出现时间（秒）", "name": "element_timeout", "tip": "超过该时间停止等待", "default": 10, "value": [{"type": "str", "value": ""}], "required": true}], "outputList": [{"types": "List", "formType": {"type": "RESULT"}, "key": "table_pick", "title": "表格对象", "tip": "输出获取的表格对象，数据类型：字典"}], "icon": "get-table-data-web", "helpManual": ""}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
