INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('31','BrowserElement.input','{"key": "BrowserElement.input", "title": "填写输入框（web）", "version": "1.0.5", "src": "astronverse.browser.browser_element.BrowserElement().input", "comment": "在指定的浏览器对象 @{browser_obj} 中拾取输入框 @{element_data} ，以 @{fill_type:键盘输入/剪贴板输入} 的形式输入内容 ，将执行结果输出至 @{form_input}", "inputList": [{"types": "Browser", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "browser_obj", "title": "浏览器对象", "name": "browser_obj", "tip": "选择要等待页面所在的浏览器对象", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "WebPick", "formType": {"type": "PICK", "params": {"use": "WebPick"}}, "key": "element_data", "title": "拾取输入框", "name": "element_data", "tip": "拾取需要填写内容的输入框元素", "required": true, "noInput": true}, {"types": "Bool", "formType": {"type": "SWITCH", "params": {}}, "key": "simulate_flag", "title": "模拟人工输入", "name": "simulate_flag", "tip": "模拟人工输入是模拟人为操作方式输入，否则将根据元素的自动化接口进行输入", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": false, "required": false}, {"types": "FillInputForFillTypeFlag", "formType": {"type": "RADIO"}, "key": "fill_type", "title": "输入类型", "name": "fill_type", "tip": "选择填写输入框的方式", "options": [{"label": "键盘输入", "value": "text"}, {"label": "剪贴板", "value": "clipboard"}, {"label": "凭据输入", "value": "credential"}], "default": "text", "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "fill_input", "title": "输入内容", "name": "fill_input", "tip": "填写输入框的内容", "default": "", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.fill_input.show", "expression": "return $this.fill_type.value == ''text''"}], "required": true}, {"types": "Str", "formType": {"type": "SELECT", "params": {"filters": ["credential"]}}, "key": "fill_input_credential", "title": "选择凭据", "name": "fill_input_credential", "tip": "", "default": "", "dynamics": [{"key": "$this.fill_input_credential.show", "expression": "return $this.fill_type.value == ''credential''"}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "element_timeout", "title": "等待元素出现时间（秒）", "name": "element_timeout", "tip": "超过该时间停止等待", "default": 10, "value": [{"type": "str", "value": ""}], "required": true}, {"types": "Float", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "focus_time", "title": "焦点睡眠时间", "name": "focus_time", "tip": "焦点停顿时间(ms)", "default": 1000, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.focus_time.show", "expression": "return $this.simulate_flag.value == true"}], "required": false}, {"types": "Float", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "write_gap_time", "title": "按键输入间隔", "name": "write_gap_time", "tip": "输入内容输入的时间间隔(s)", "default": 0, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.write_gap_time.show", "expression": "return $this.simulate_flag.value == true"}], "required": false}, {"types": "FillInputForInputTypeFlag", "formType": {"type": "RADIO"}, "key": "input_type", "title": "追加输入", "name": "input_type", "tip": "是否对输入框进行追加输入", "options": [{"label": "追加", "value": "append"}, {"label": "覆盖", "value": "overwrite"}], "default": "overwrite", "required": true}, {"types": "Bool", "formType": {"type": "SWITCH", "params": {}}, "key": "scroll_into_center", "title": "元素滚动到可视区域中心", "name": "scroll_into_center", "tip": "选择是否将元素滚动到可视区域中心位置，若部分网页可能错位，可选择关闭此功能", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": true, "dynamics": [{"key": "$this.scroll_into_center.show", "expression": "return $this.simulate_flag.value == true"}], "required": false}], "outputList": [{"types": "Str", "formType": {"type": "RESULT"}, "key": "form_input", "title": "用户输入内容", "tip": ""}], "icon": "fill-input-web", "helpManual": ""}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('32','BrowserElement.loop_similar','{"key": "BrowserElement.loop_similar", "title": "循环相似元素列表（web）", "version": "1.0.5", "src": "astronverse.browser.browser_element.BrowserElement().loop_similar", "comment": "获取浏览器对象 @{browser_obj} 中与拾取到的元素 @{element_data} 相似的元素，从起始项@{start}到结束项@{end}进行循环操作，输出列表循环至@{item}, 是否输出循环项位置为@{index}", "inputList": [{"types": "Browser", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "browser_obj", "title": "浏览器对象", "name": "browser_obj", "tip": "选择相似元素所在的浏览器对象", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "WebPick", "formType": {"type": "PICK", "params": {"use": "WebPick"}}, "key": "element_data", "title": "相似元素拾取", "name": "element_data", "tip": "在网页上拾取不同位置的两个相似元素", "required": true, "noInput": true}, {"types": "ElementGetAttributeHasSelfTypeFlag", "formType": {"type": "SELECT"}, "key": "get_type", "title": "元素操作", "name": "get_type", "tip": "", "options": [{"label": "获取元素对象", "value": "getElement"}, {"label": "获取元素文本内容", "value": "getText"}, {"label": "获取元素源代码", "value": "getHtml"}, {"label": "获取元素值", "value": "getValue"}, {"label": "获取元素链接地址", "value": "getLink"}, {"label": "获取元素属性", "value": "getAttribute"}, {"label": "获取元素位置", "value": "getPosition"}, {"label": "获取元素选中状态", "value": "getSelection"}, {"label": "获取元素样式", "value": "getStyle"}], "default": "getElement", "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "start", "title": "起始位置", "name": "start", "tip": "下标位置从0开始", "default": 0, "value": [{"type": "str", "value": ""}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "end", "title": "结束位置", "name": "end", "tip": "下标位置从0开始,-1代表循环至最后一个元素", "default": -1, "value": [{"type": "str", "value": ""}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "attribute_name", "title": "属