pes": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "file_name", "title": "自定义文件名", "name": "file_name", "tip": "不需要输入扩展名，系统会自动添加扩展名【系统建议打开显示扩展名】", "default": "", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.file_name.show", "expression": "return $this.custom_flag.value == true"}], "required": true}, {"types": "Bool", "formType": {"type": "SWITCH", "params": {}}, "key": "simulate_flag", "title": "模拟人工点击", "name": "simulate_flag", "tip": "模拟人工点击是模拟人为操作方式点击，否则将根据拾取元素的自动化接口进行点击", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": true, "dynamics": [{"key": "$this.simulate_flag.show", "expression": "return $this.download_mode.value == ''click''"}], "required": false}, {"types": "Bool", "formType": {"type": "SWITCH", "params": {}}, "key": "is_wait", "title": "同步等待", "name": "is_wait", "tip": "", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": true, "required": false}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "time_out", "title": "最长等待时间", "name": "time_out", "tip": "超过最长等待时间（秒）则停止等待", "default": 60, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.time_out.show", "expression": "return $this.is_wait.value == true"}], "required": false}], "outputList": [{"types": "Str", "formType": {"type": "RESULT"}, "key": "load_file", "title": "文档路径", "tip": ""}], "icon": "file-download-web", "helpManual": ""}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
