INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('92','CV.cv_click','{"key": "CV.cv_click", "title": "点击图像", "version": "1.0.1", "src": "astronverse.vision.cv.CV().cv_click", "comment": "鼠标(@{btn_type})(@{btn_model})图像(@{input_data})(@{click_position})", "inputList": [{"types": "IMGPick", "formType": {"type": "PICK", "params": {"use": "CV"}}, "key": "input_data", "title": "目标图像", "name": "input_data", "tip": "支持从图形库中选择或拾取图像获取图像元素", "required": true, "noInput": true}, {"types": "BtnType", "formType": {"type": "RADIO"}, "key": "btn_type", "title": "鼠标按键", "name": "btn_type", "tip": "", "options": [{"label": "左键", "value": "left"}, {"label": "中键", "value": "middle"}, {"label": "右键", "value": "right"}], "default": "left", "required": false}, {"types": "BtnModel", "formType": {"type": "RADIO"}, "key": "btn_model", "title": "点击方式", "name": "btn_model", "tip": "", "options": [{"label": "单击", "value": "click"}, {"label": "双击", "value": "double_click"}], "default": "click", "required": false}, {"types": "PositionType", "formType": {"type": "RADIO"}, "key": "click_position", "title": "点击位置", "name": "click_position", "tip": "选择鼠标点击位置", "options": [{"label": "中心点", "value": "center"}, {"label": "随机位置", "value": "random"}, {"label": "指定位置", "value": "specific"}], "default": "center", "required": false}, {"types": "Any", "formType": {"type": "GRID"}, "key": "specified_position", "title": "指定位置", "name": "specified_position", "tip": "", "default": 5, "dynamics": [{"key": "$this.specified_position.show", "expression": "return $this.click_position.value == ''specific''"}], "required": false}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "horizontal_move", "title": "横向平移", "name": "horizontal_move", "tip": "", "default": 0, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.horizontal_move.show", "expression": "return $this.click_position.value == ''specific''"}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "vertical_move", "title": "纵向平移", "name": "vertical_move", "tip": "", "default": 0, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.vertical_move.show", "expression": "return $this.click_position.value == ''specific''"}], "required": true}, {"types": "Float", "formType": {"type": "SLIDER"}, "key": "match_similarity", "title": "匹配相似度", "name": "match_similarity", "tip": "查找目标图像与当前页面的相似度阈值(最高匹配精确度为99%)，精准匹配表示当前界面存在于截取的目标图像完全一致的时候才能匹配成功", "default": 0.95, "required": false}, {"types": "MoveType", "formType": {"type": "RADIO"}, "key": "move_type", "title": "鼠标移动方式", "name": "move_type", "tip": "", "options": [{"label": "匀速直线", "value": "linear"}, {"label": "模拟人工", "value": "simulation"}, {"label": "瞬时移动", "value": "teleportation"}], "default": "linear", "required": false}, {"types": "Speed", "formType": {"type": "RADIO"}, "key": "move_speed", "title": "鼠标移动速度", "name": "move_speed", "tip": "", "options": [{"label": "慢速", "value": "slow"}, {"label": "正常", "value": "normal"}, {"label": "快速", "value": "fast"}], "default": "normal", "dynamics": [{"key": "$this.move_speed.show", "expression": "return [''linear'',''simulation''].includes($this.move_type.value)"}], "required": false}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "wait_time", "title": "等待图像出现时间(秒)", "name": "wait_time", "tip": "超过该时间停止等待，默认为10秒", "default": 10, "value": [{"type": "str", "value": ""}], "required": false}], "outputList": [], "icon": "click-image", "helpManual": "在当前(激活)窗口检索目标图片，并在窗口界面中点击该图片。"}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('93','CV.hover_image','{"key": "CV.hover_image", "title": "鼠标悬浮在图像上", "version": "1.0.1", "src": "astronverse.vision.cv.CV().hover_image", "comment": "鼠标悬浮在图像(@{input_data})的(@{click_position})", "inputList": [{"types": "IMGPick", "formType": {"type": "PICK", "params": {"use": "CV"}}, "key": "input_data", "title": "目标图像", "name": "input_data", "tip": "支持从图形库中选择或拾取图像获取图像元素", "required": true, "noInput": true}, {"types": "PositionType", "formType": {"type": "RADIO"}, "key": "click_position", "title": "悬浮位置", "name": "click_position", "tip": "", "options": [{"label": "中心点", "value": "center"}, {"label": "随机位置", "value": "random"}, {"label": "指定位置", "value": "specific"}], "default": "center", "required": false}, {"types": "Any", "formType": {"type": "GRID"}, "key": "specified_position", "title": "指定位置", "name": "specified_position", "tip": "按照九宫格切割图像，支持选择九宫格任意一个区域，选择区域则悬浮在目标图像对应区域的中心点位置", "default": 5, "dynamics": [{"key": "$this.specified_position.show", "expression": "return $this.click_position.value == ''specific''"}], "required": false}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "horizontal_move", "title": "横向平移", "name": "horizontal_move", "tip": "", "default": 0, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.horizontal_move.show", "expression": "return $this.click_position.value == ''specific''"}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "vertical_move", "title": "纵向平移", "name": "vertical_move", "tip": "", "default": 0, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.vertical_move.show", "expression": "return $this.click_position.value == ''specific''"}], "required": true}, {"types": "Float", "formType": {"type": "SLIDER"}, "key": "match_similarity", "title": "匹配相似度", "name": "match_similarity", "tip": "查找目标图像与当前页面的相似度阈值(最高匹配精确度为99%)，精准匹配表示当前界面存在于截取的目标图像完全一致的时候才能匹配成功", "default": 0.95, "required": false}, {"types": "MoveType", "formType": {"type": "RADIO"}, "key": "move_type", "title": "鼠标移动方式", "name": "move_type", "tip": "", "options": [{"label": "匀速直线", "value": "linear"}, {"label": "模拟人工", "value": "simulation"}, {"label": "瞬时移动", "value": "teleportation"}], "default": "linear", "required": false}, {"types": "Speed", "formType": {"type": "RADIO"}, "key": "move_speed", "title": "鼠标移动速度", "name": "move_speed", "tip": "", "options": [{"label": "慢速", "value": "slow"}, {"label": "正常", "value": "normal"}, {"label": "快速", "value": "fast"}], "default": "normal", "dynamics": [{"key": "$this.move_speed.show", "expression": "return [''linear'',''simulation''].includes($this.move_type.value)"}], "required": false}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "wait_time", "title": "等待图像出现时间(秒)", "name": "wait_time", "tip": "超过该时间停止等待，默认为10秒", "default": 10, "value": [{"type": "str", "value": ""}], "required": false}], "outputList": [], "icon": "mouse-hover-image", "helpManual": "在当前(激活)窗口检索图像，并将鼠标移动到该图像的指定位置上。"}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('94','CV.image_input','{"key": "CV.image_input", "title": "图像输入框输入", "version": "1.0.1", "src": "astronverse.vision.cv.CV().image_input", "comment": "拾取图像输入框(@{input_data})以(@{input_type})输入(@{input_content})", "inputList": [{"types": "IMGPick", "formType": {"type": "PICK", "params": {"use": "CV"}}, "key": "input_data", "title": "目标图像", "name": "input_data", "tip": "支持从图形库中选择或拾取图像获取图像元素", "required": true, "noInput": true}, {"types": "InputType", "formType": {"type": "RADIO"}, "key": "input_type", "title": "输入方式", "name": "input_type", "tip": "", "options": [{"label": "字符输入", "value": "text"}, {"label": "剪切板输入", "value": "clip"}], "default": "text", "required": false}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "input_content", "title": "输入内容", "name": "input_content", "tip": "", "default": "", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.input_content.show", "expression": "return $this.input_type.value == ''text''"}], "required": true}, {"types": "Simulate_flag", "formType": {"type": "SWITCH"}, "key": "simulate_flag", "title": "模拟人工输入", "name": "simulate_flag", "tip": "", "options": [{"label": "是", "value": "yes"}, {"label": "否", "value": "no"}], "default": "yes", "dynamics": [{"key": "$this.simulate_flag.show", "expression": "return $this.input_type.value == ''text''"}], "required": false}, {"types": "Float", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "interval", "title": "输入间隔", "name": "interval", "tip": "", "default": 0.1, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.interval.show", "expression": "return $this.input_type.value == ''text''"}], "required": false}, {"types": "Float", "formType": {"type": "SLIDER"}, "key": "match_similarity", "title": "匹配相似度", "name": "match_similarity", "tip": "", "default": 0.95, "required": false}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "wait_time", "title": "等待图像出现时间(秒)", "name": "wait_time", "tip": "超过该时间停止等待，默认为10秒", "default": 10, "value": [{"type": "str", "value": ""}], "required": false}], "outputList": [], "icon": "image-input-box", "helpManual": "点击目标输入框的图像，并输入内容"}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('95','CV.is_image_exist','{"key": "CV.is_image_exist", "title": "IF图像存在", "version": "1.0.1", "src": "astronverse.vision.cv.CV().is_image_exist", "comment": "判断图像(@{input_data})在当前界面(@{exist_type})", "inputList": [{"types": "IMGPick", "formType": {"type": "PICK", "params": {"use": "CV"}}, "key": "input_data", "title": "目标图像", "name": "input_data", "tip": "支持从图形库中选择或拾取图像获取图像元素", "required": true, "noInput": true}, {"types": "ExistType", "formType": {"type": "RADIO"}, "key": "exist_type", "title": "判断类型", "name": "exist_type", "tip": "判断图像存在或不存在，分别执行对应代码块内容", "options": [{"label": "存在", "value": "exist"}, {"label": "不存在", "value": "not_exist"}], "default": "exist", "required": false}, {"types": "Float", "formType": {"type": "SLIDER"}, "key": "match_similarity", "title": "匹配相似度", "name": "match_similarity", "tip": "查找目标图像与当前页面的相似度阈值(最高匹配精确度为99%)，精准匹配表示当前界面存在于截取的目标图像完全一致的时候才能匹配成功", "default": 0.95, "required": false}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "wait_time", "title": "等待图像时间(秒)", "name": "wait_time", "tip": "超过该时间停止等待，默认为10秒", "default": 10, "value": [{"type": "str", "value": ""}], "required": false}], "outputList": [], "icon": "if-image-exists", "helpManual": "在当前(激活)窗口检索图像，判断是否存在。"}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('96','CV.wait_image','{"key": "CV.wait_image", "title": "等待图像", "version": "1.0.1", "src": "astronverse.vision.cv.CV().wait_image", "comment": "等待图像(@{input_data})(@{wait_type})", "inputList": [{"types": "IMGPick", "formType": {"type": "PICK", "params": {"use": "CV"}}, "key": "input_data", "title": "目标图像", "name": "input_data", "tip": "支持从图形库中选择或拾取图像获取图像元素", "required": true, "noInput": true}, {"types": "WaitType", "formType": {"type": "RADIO"}, "key": "wait_type", "title": "等待类型", "name": "wait_type", "tip": "等待图像出现或消失", "options": [{"label": "图像出现", "value": "appear"}, {"label": "图像消失", "value": "disappear"}], "default": "appear", "required": false}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "wait_time", "title": "等待时间(秒)", "name": "wait_time", "tip": "超过该时间停止等待，默认为10秒", "default": 10, "value": [{"type": "str", "value": ""}], "required": false}, {"types": "Float", "formType": {"type": "SLIDER"}, "key": "match_similarity", "title": "匹配相似度", "name": "match_similarity", "tip": "查找目标图像与当前页面的相似度阈值(最高匹配精确度为99%)，精准匹配表示当前界面存在于截取的目标图像完全一致的时候才能匹配成功", "default": 0.95, "required": false}], "outputList": [{"types": "Bool", "formType": {"type": "RESULT"}, "key": "image_wait_result", "title": "等待结果", "tip": "目标图像是否出现/消失，在等待时间内出现/消失为true，反之为false"}], "icon": "wait-image", "helpManual": "等待目标图像出现或消失，再继续执行流程。"}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('97','DataConvertProcess.json_convertor','{"key": "DataConvertProcess.json_convertor", "title": "JSON字符串互转", "version": "1.0.2", "src": "astronverse.dataprocess.dataconvert.DataConvertProcess().json_convertor", "comment": "将输入文本 @{input_data} 从JSON格式转换为字符串或从字符串格式转换为JSON格式，返回转换后的文本 @{json_convert_data}", "inputList": [{"types": "Any", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "input_data", "title": "输入内容", "name": "input_data", "tip": "", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "JSONConvertType", "formType": {"type": "RADIO"}, "key": "convert_type", "title": "转换类型", "name": "convert_type", "tip": "", "options": [{"label": "JSON转字符串", "value": "json_to_str"}, {"label": "字符串转JSON", "value": "str_to_json"}], "default": "json_to_str", "required": true}], "outputList": [{"types": "Any", "formType": {"type": "RESULT"}, "key": "json_convert_data", "title": "转换结果", "tip": ""}], "icon": "json-string-convert", "helpManual": ""}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
