INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('99','DataConvertProcess.str_to_other','{"key": "DataConvertProcess.str_to_other", "title": "文本转其他格式", "version": "1.0.2", "src": "astronverse.dataprocess.dataconvert.DataConvertProcess().str_to_other", "comment": "将输入文本（字符串） @{input_data} 转换为其他格式，返回转换后的结果 @{str_convert_other}", "inputList": [{"types": "Any", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "input_data", "title": "输入内容", "name": "input_data", "tip": "", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "StringConvertType", "formType": {"type": "SELECT"}, "key": "convert_type", "title": "转换类型", "name": "convert_type", "tip": "", "options": [{"label": "字符串转列表", "value": "str_to_list"}, {"label": "字符串转字典", "value": "str_to_dict"}, {"label": "字符串转元组", "value": "str_to_tuple"}, {"label": "字符串转布尔值", "value": "str_to_bool"}, {"label": "字符串转整数", "value": "str_to_int"}, {"label": "字符串转浮点数", "value": "str_to_float"}], "default": "str_to_int", "required": true}], "outputList": [{"types": "Any", "formType": {"type": "RESULT"}, "key": "str_convert_other", "title": "转换结果", "tip": ""}], "icon": "text-convert-format", "helpManual": ""}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('100','DataProcess.set_variable_value','{"key": "DataProcess.set_variable_value", "title": "设置变量值", "version": "1.0.2", "src": "astronverse.dataprocess.data.DataProcess().set_variable_value", "comment": "赋值 @{value} 给变量 @{variable_var}", "inputList": [{"types": "Any", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "value", "title": "变量值", "name": "value", "tip": "输入需要设置的变量值", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "VariableType", "formType": {"type": "SELECT"}, "key": "variable_type", "title": "变量类型", "name": "variable_type", "tip": "选择需要设置的变量类型", "options": [{"label": "字符串", "value": "str"}, {"label": "整数", "value": "int"}, {"label": "浮点数", "value": "float"}, {"label": "布尔值", "value": "bool"}, {"label": "列表", "value": "list"}, {"label": "字典", "value": "dict"}, {"label": "JSON", "value": "json"}, {"label": "元组", "value": "tuple"}, {"label": "其他", "value": "other"}], "default": "int", "required": true}], "outputList": [{"types": "Str", "formType": {"type": "RESULT"}, "key": "variable_var", "title": "设置后的变量值", "tip": "", "dynamics": [{"key": "$this.variable_var.types", "expression": "return [''int'',''str'', ''float'', ''bool'', ''list'', ''dict''].includes($this.variable_type.value) ? $this.variable_type.value[0].toUpperCase() + $this.variable_type.value.slice(1) : ''Any''"}]}], "icon": "set-variable-value", "helpManual": ""}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('101','Dialog.custom_box','{"key": "Dialog.custom_box", "title": "自定义对话框", "version": "1.0.2", "src": "astronverse.dialog.dialog.Dialog().custom_box", "comment": "", "inputList": [{"types": "Str", "formType": {"type": "INPUT"}, "key": "box_title", "title": "对话框标题", "name": "box_title", "tip": "", "default": "自定义对话框", "required": true, "limitLength": [-1, 50]}, {"types": "Str", "formType": {"type": "MODALBUTTON"}, "key": "design_interface", "title": "设计对话框界面", "name": "design_interface", "tip": "点击按钮则进入对话框设计弹窗界面", "need_parse": "json_str", "required": false}, {"types": "Bool", "formType": {"type": "SWITCH"}, "key": "auto_check", "title": "无操作自动关闭对话框", "name": "auto_check", "tip": "", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": false, "required": false}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "wait_time", "title": "无操作超时等待（秒）", "name": "wait_time", "tip": "", "default": 60, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.wait_time.show", "expression": "return $this.auto_check.value == true"}], "required": false}, {"types": "DefaultButtonCN", "formType": {"type": "SELECT"}, "key": "default_button", "title": "超时默认选中按钮", "name": "default_button", "tip": "", "options": [{"label": "确认", "value": "confirm"}, {"label": "取消", "value": "cancel"}], "default": "confirm", "dynamics": [{"key": "$this.default_button.show", "expression": "return $this.auto_check.value == true"}], "required": true}], "outputList": [{"types": "DialogResult", "formType": {"type": "RESULT"}, "key": "dialog_result", "title": "自定义对话框结果", "tip": "存储所有表单控件的输出结果以及点击的按钮结果"}], "icon": "custom-dialog", "helpManual": ""}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('102','Dialog.input_box','{"key": "Dialog.input_box", "title": "输入对话框", "version": "1.0.2", "src": "astronverse.dialog.dialog.Dialog().input_box", "comment": "", "inputList": [{"types": "Str", "formType": {"type": "INPUT"}, "key": "box_title", "title": "对话框标题", "name": "box_title", "tip": "限制标题内容字符数量为50个字符，不输入则默认标题为“输入对话框”", "default": "输入对话框", "required": false, "limitLength": [-1, 50]}, {"types": "InputType", "formType": {"type": "RADIO"}, "key": "input_type", "title": "输入框类型", "name": "input_type", "tip": "", "options": [{"label": "文本框", "value": "text"}, {"label": "密码框", "value": "password"}, {"label": "多行文本框", "value": "textarea"}], "default": "text", "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "input_title", "title": "输入框标题", "name": "input_title", "tip": "", "default": "输入框标题", "value": [{"type": "str", "value": ""}], "required": false, "limitLength": [-1, 60]}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "default_input_text", "title": "输入框内容默认值", "name": "default_input_text", "tip": "填写则在对话框中展示默认文本作为文本提示符，限制内容字符数量为120个字符", "default": "", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.default_input_text.show", "expression": "return $this.input_type.value != ''password''"}], "required": false}, {"types": "Str", "formType": {"type": "DEFAULTPASSWORD"}, "key": "default_input_pwd", "title": "输入框内容默认值", "name": "default_input_pwd", "tip": "填写则在对话框中展示默认密码，密码长度在4-16位之间", "default": "", "dynamics": [{"key": "$this.default_input_pwd.show", "expression": "return $this.input_type.value == ''password''"}], "required": false, "limitLength": [4, 16]}, {"types": "Any", "formType": {"type": "MODALBUTTON"}, "key": "preview_button", "title": "预览", "name": "preview_button", "tip": "", "required": false}], "outputList": [{"types": "Str", "formType": {"type": "RESULT"}, "key": "input_content", "title": "保存用户输入内容至", "tip": ""}, {"types": "Str", "formType": {"type": "RESULT"}, "key": "result_button", "title": "保存点击的按钮名称至", "tip": ""}], "icon": "input-dialog", "helpManual": "打开输入对话框，需用户进行信息输入并确定提交，返回用户在对话框中输入的内容。"}',NULL,'2025-10-11 14:12:21','2026-08-16 10:34:02');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('103','Dialog.message_box','{"key": "Dialog.message_box", "title": "消息提示框", "version": "1.0.2", "src": "astronverse.dialog.dialog.Dialog().message_box", "comment": "", "inputList": [{"types": "Str", "formType": {"type": "INPUT"}, "key": "box_title", "title": "对话框标题", "name": "box_title", "tip": "用户自定义的对话框上方的显示标题，限制标题内容字符数量为50个字符。不输入则默认标题为“消息提示框”", "default": "消息提示框", "required": false, "limitLength": [-1, 50]}, {"types": "MessageType", "formType": {"type": "RADIO"}, "key": "message_type", "title": "消息类型", "name": "message_type", "tip": "可选消息类型", "options": [{"label": "信息", "value": "message"}, {"label": "警告", "value": "warning"}, {"label": "问题", "value": "question"}, {"label": "错误", "value": "error"}], "default": "message", "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "message_content", "title": "消息内容", "name": "message_content", "tip": "用户自定义的对话框内的显示内容，限制内容字符数量为120个字符", "default": "", "required": true, "limitLength": [-1, 120]}, {"types": "ButtonType", "formType": {"type": "SELECT"}, "key": "button_type", "title": "展示按钮", "name": "button_type", "tip": "消息框可展示给用户进行选择的按钮，只允许切换，不允许空选状态", "options": [{"label": "确认", "value": "confirm"}, {"label": "确认-取消", "value": "confirm_cancel"}, {"label": "是-否", "value": "yes_no"}, {"label": "是-否-取消", "value": "yes_no_cancel"}], "default": "confirm", "required": true}, {"types": "Bool", "formType": {"type": "SWITCH"}, "key": "auto_check", "title": "无操作自动关闭对话框", "name": "auto_check", "tip": "", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": false, "required": false}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "wait_time", "title": "无操作超时等待（秒）", "name": "wait_time", "tip": "设置超时等待时间，未识别到用户鼠标移动行为超过该时间则选中默认按钮，默认为60秒", "default": 60, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.wait_time.show", "expression": "return $this.auto_check.value == true"}], "required": false}, {"types": "DefaultButtonC", "formType": {"type": "SELECT"}, "key": "default_button_c", "title": "超时默认选中按钮", "name": "default_button_c", "tip": "", "options": [{"label": "确认", "value": "confirm"}], "default": "confirm", "dynamics": [{"key": "$this.default_button_c.show", "expression": "return $this.auto_check.value == true && $this.button_type.value == ''confirm''"}], "required": true}, {"types": "DefaultButtonCN", "formType": {"type": "SELECT"}, "key": "default_button_cn", "title": "超时默认选中按钮", "name": "default_button_cn", "tip": "", "options": [{"label": "确认", "value": "confirm"}, {"label": "取消", "value": "cancel"}], "default": "confirm", "dynamics": [{"key": "$this.default_button_cn.show", "expression": "return $this.auto_check.value == true && $this.button_type.value == ''confirm_cancel''"}], "required": true}, {"types": "DefaultButtonY", "formType": {"type": "SELECT"}, "key": "default_button_y", "title": "超时默认选中按钮", "name": "default_button_y", "tip": "", "options": [{"label": "是", "value": "yes"}, {"label": "否", "value": "no"}], "default": "yes", "dynamics": [{"key": "$this.default_button_y.show", "expression": "return $this.auto_check.value == true && $this.button_type.value == ''yes_no''"}], "required": true}, {"types": "DefaultButtonYN", "formType": {"type": "SELECT"}, "key": "default_button_yn", "title": "超时默认选中按钮", "name": "default_button_yn", "tip": "", "options": [{"label": "是", "value": "yes"}, {"label": "否", "value": "no"}, {"label": "取消", "value": "cancel"}], "default": "yes", "dynamics": [{"key": "$this.default_button_yn.show", "expression": "return $this.auto_check.value == true && $this.button_type.value == ''yes_no_cancel''"}], "required": true}, {"types": "Any", "formType": {"type": "MODALBUTTON"}, "key": "preview_button", "title": "预览", "name": "preview_button", "tip": "", "required": false}], "outputList": [{"types": "Str", "formType": {"type": "RESULT"}, "key": "result_button", "title": "保存用户选择的按钮至", "tip": ""}], "icon": "message-dialog", "helpManual": "打开消息提示对话框，可设定消息提示的内容和标题。"}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
