ice.show", "expression": "return $this.open_type.value == ''file''"}], "required": false}, {"types": "Str", "formType": {"type": "INPUT"}, "key": "select_title", "title": "选择框标题", "name": "select_title", "tip": "", "default": "", "required": false, "limitLength": [-1, 60]}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON_FILE", "params": {"filters": [], "file_type": "folder"}}, "key": "default_path", "title": "默认文件夹", "name": "default_path", "tip": "当配置了该参数，则在打开文件选择框时默认解析在该文件夹路径进行下一步选择", "default": "", "required": false}, {"types": "Any", "formType": {"type": "MODALBUTTON"}, "key": "preview_button", "title": "预览", "name": "preview_button", "tip": "", "required": false}], "outputList": [{"types": "Any", "formType": {"type": "RESULT"}, "key": "select_file", "title": "保存文件选择结果至", "tip": "保存用户的文件选择结果，如果用户点击取消按钮则返回为空值"}], "icon": "file-select-dialog", "helpManual": "打开系统选择文件对话框，保存用户选择的对应的文件/文件夹路径"}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
