INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('116','Docx.close_docx','{"key": "Docx.close_docx", "title": "关闭Word", "version": "1.0.2", "src": "astronverse.word.docx.Docx().close_docx", "comment": "关闭Word对象 @{doc}", "inputList": [{"types": "DocumentObject", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "doc", "title": "Word对象", "name": "doc", "tip": "本软件前序原子能力（如打开、创建）返回的Word对象", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "CloseRangeType", "formType": {"type": "RADIO"}, "key": "close_range_flag", "title": "关闭文档范围", "name": "close_range_flag", "tip": "选择关闭文档的范围，如关闭当前文档或关闭所有文档", "options": [{"label": "关闭当前文档", "value": "one"}, {"label": "关闭所有文档", "value": "all"}], "default": "one", "required": true}, {"types": "SaveType", "formType": {"type": "RADIO"}, "key": "save_type", "title": "保存类型", "name": "save_type", "tip": "选择保存类型，如保存、另存为、不保存", "options": [{"label": "保存", "value": "save"}, {"label": "另存为", "value": "save_as"}, {"label": "不保存", "value": "abort"}], "default": "save", "dynamics": [{"key": "$this.save_type.show", "expression": "return $this.close_range_flag.value == ''one''"}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON_FILE", "params": {"filters": [], "file_type": "folder"}}, "key": "file_path", "title": "另存为文档路径", "name": "file_path", "tip": "填写Word的保存路径", "default": "", "dynamics": [{"key": "$this.file_path.show", "expression": "return $this.save_type.value == ''save_as'' && $this.close_range_flag.value == ''one''"}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "file_name", "title": "另存为文档名称", "name": "file_name", "tip": "填写Word的名称", "default": "", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.file_name.show", "expression": "return $this.save_type.value == ''save_as'' && $this.close_range_flag.value == ''one''"}], "required": true}, {"types": "FileExistenceType