INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('153','Excel.delete_excel_cell','{"key": "Excel.delete_excel_cell", "title": "删除Excel单元格", "version": "1.0.1", "src": "astronverse.excel.excel.Excel().delete_excel_cell", "comment": "删除Excel对象 @{excel} 中工作表 @{sheet_name} 的单元格", "inputList": [{"types": "ExcelObj", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "excel", "title": "Excel对象", "name": "excel", "tip": "", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "sheet_name", "title": "工作表名", "name": "sheet_name", "tip": "输入需编辑的工作表名称，如''Sheet1''，为空默认使用Excel中的第一个工作表对象", "default": "", "value": [{"type": "str", "value": ""}], "required": false}, {"types": "ReadRangeType", "formType": {"type": "SELECT"}, "key": "delete_range_excel", "title": "删除范围", "name": "delete_range_excel", "tip": "", "options": [{"label": "单元格", "value": "cell"}, {"label": "行", "value": "row"}, {"label": "列", "value": "column"}, {"label": "区域", "value": "area"}, {"label": "已编辑区域", "value": "all"}], "default": "cell", "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "coordinate", "title": "单元格位置", "name": "coordinate", "tip": "输入单元格位置，如A1", "default": "", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.coordinate.show", "expression": "return $this.delete_range_excel.value == ''cell''"}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "row", "title": "行", "name": "row", "tip": "输入整数代表行号，从1开始", "default": "", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.row.show", "expression": "return $this.delete_range_excel.value == ''row''"}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "col", "title": "列", "name": "col", "tip": "输入列名，支持输入字符A或者整数1", "default": "", "value": [{"type": "str", "value"