ult": 1, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.col.show", "expression": "return $this.insert_type.value == ''column''"}], "required": true}, {"types": "ColumnDirectionType", "formType": {"type": "RADIO"}, "key": "col_direction", "title": "插入列方向", "name": "col_direction", "tip": "", "options": [{"label": "向左插入", "value": "left"}, {"label": "向右插入", "value": "right"}], "default": "right", "dynamics": [{"key": "$this.col_direction.show", "expression": "return $this.insert_type.value == ''column''"}], "required": true}, {"types": "Bool", "formType": {"type": "SWITCH", "params": {}}, "key": "blank_rows", "title": "是否只插入空行/空列", "name": "blank_rows", "tip": "", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": false, "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "insert_num", "title": "插入行数", "name": "insert_num", "tip": "", "default": 1, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.insert_num.show", "expression": "return $this.blank_rows.value == true"}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "insert_content", "title": "插入内容", "name": "insert_content", "tip": "插入单行或多行时，插入内容需为多维列表，字符需使用单引号''''，例：插入1行，写入内容：[[123,24,32]]，插入2行，写入内容：[[123,123],[''aaa'']]，则实际写入excel内容为：第一行：123  123；第二行：aaa；写入内容：[[123,123],''aaa'']，则实际写入excel内容为：第一行：123  123；第二行：a a a；如果插入的行或列超过数据长度，多余的单元格将保持为空", "default": "", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.insert_content.show", "expression": "return $this.blank_rows.value == false"}], "required": true}], "outputList": [], "icon": "excel-insert-row-column", "helpManual": ""}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
