INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('180','Excel.search_and_replace_excel_content','{"key": "Excel.search_and_replace_excel_content", "title": "查找或替换Excel内容", "version": "1.0.1", "src": "astronverse.excel.excel.Excel().search_and_replace_excel_content", "comment": "查找或替换Excel对象 @{excel} 中 @{search_range} 范围内 @{find_str} ，返回查找结果 @{search_excel_result}", "inputList": [{"types": "ExcelObj", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "excel", "title": "Excel对象", "name": "excel", "tip": "", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "find_str", "title": "查找内容", "name": "find_str", "tip": "", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "Bool", "formType": {"type": "SWITCH", "params": {}}, "key": "replace_flag", "title": "是否替换", "name": "replace_flag", "tip": "", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": false, "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "replace_str", "title": "替换内容", "name": "replace_str", "tip": "", "default": "", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.replace_str.show", "expression": "return $this.replace_flag.value == true"}], "required": true}, {"types": "SearchSheetType", "formType": {"type": "RADIO"}, "key": "lookup_range_excel", "title": "查找范围", "name": "lookup_range_excel", "tip": "", "options": [{"label": "全部工作表", "value": "all"}, {"label": "单个工作表", "value": "one"}], "default": "all", "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "sheet_name", "title": "工作表名", "name": "sheet_name", "tip": "输入需编辑的工作表名称，如''Sheet1''，为空默认使用Excel中的第一个工作表对象", "default": "", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.sheet_name.show", "expression": "return $this.lookup_range_excel.value == ''one''"}], "required": false}, {"types": "SearchRangeType", "formType": {"type": "SELECT"}, "key": "search_range", "title": "工作表内查找范围", "name": "search_range", "tip": "", "options": [{"label": "已编辑区域", "value": "all"}, {"label": "行", "value": "row"}, {"label": "列", "value": "column"}, {"label": "区域", "value": "area"}], "default": "all", "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "row", "title": "行", "name": "row", "tip": "输入整数代表行号，从1开始", "default": "", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.row.show", "expression": "return $this.search_range.value == ''row''"}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "col", "title": "列", "name": "col", "tip": "输入列名，支持输入字符A或者整数1", "default": "", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.col.show", "expression": "return $this.search_range.value == ''column''"}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "start_row", "title": "起始行", "name": "start_row", "tip": "", "default": "", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.start_row.show", "expression": "return $this.search_range.value == ''area''"}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "end_row", "title": "结束行", "name": "end_row", "tip": "", "default": "", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.end_row.show", "expression": "return $this.search_range.value == ''area''"}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "start_col", "title": "起始列", "name": "start_col", "tip": "输入列名，支持输入字符A或者整数1", "default": "", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.start_col.show", "expression": "return $this.search_range.value == ''area''"}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "end_col", "title": "结束列", "name": "end_col", "tip": "输入列名，支持输入字符A或者整数1，-n代表倒数第n列", "default": "", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.end_col.show", "expression": "return $this.search_range.value == ''area''"}], "required": true}, {"types": "Bool", "formType": {"type": "SWITCH", "params": {}}, "key": "exact_match", "title": "是否精确匹配", "name": "exact_match", "tip": "", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": false, "required": true}, {"types": "Bool", "formType": {"type": "SWITCH", "params": {}}, "key": "case_flag", "title": "是否区分大小写", "name": "case_flag", "tip": "", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": false, "required": true}, {"types": "MatchCountType", "formType": {"type": "RADIO"}, "key": "match_range", "title": "匹配数量", "name": "match_range", "tip": "", "options": [{"label": "所有结果", "value": "all"}, {"label": "第一个结果", "value": "first"}], "default": "all", "required": true}, {"types": "SearchResultType", "formType": {"type": "RADIO"}, "key": "output_type", "title": "输出类型", "name": "output_type", "tip": "默认返回单元格位置，比如[''A1'', ''B2'']，也可以选择分开返回行列号，比如[[''A'', 1], [''B'', 2]]", "options": [{"label": "返回单元格位置", "value": "cell"}, {"label": "返回列号和行号", "value": "col_and_row"}], "default": "cell", "required": true}], "outputList": [{"types": "Dict", "formType": {"type": "RESULT"}, "key": "search_excel_result", "title": "查找结果", "tip": "选择单工作表查找是返回单元格位置列表，比如[''A1'', ''B2'']，选择多工作表查找是返回工作表名称和单元格位置列表字典，比如{''Sheet1'': [''A1'', ''B2''], ''Sheet2'': [''C3'', ''D4'']}"}], "icon": "excel-find-replace", "helpManual": ""}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('181','File.file_copy','{"key": "File.file_copy", "title": "复制文件", "version": "1.0.1", "src": "astronverse.system.file.File().file_copy", "comment": "复制文件 @{file_path} 到指定目录 @{target_path} 下，并保存复制后的文件路径 @{copy_file_path}", "inputList": [{"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON_FILE", "params": {"filters": [], "file_type": "file"}}, "key": "file_path", "title": "待复制文件", "name": "file_path", "tip": "选择或输入待复制文件路径", "default": "", "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON_FILE", "params": {"filters": [], "file_type": "folder"}}, "key": "target_path", "title": "指定目录", "name": "target_path", "tip": "选择或输入目标目录", "default": "", "required": true}, {"types": "StateType", "formType": {"type": "RADIO"}, "key": "state_type", "title": "目录不存在时", "name": "state_type", "tip": "设置指定目录不存在时执行的操作", "options": [{"label": "创建", "value": "create"}, {"label": "提示并报错", "value": "error"}], "default": "error", "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON", "params": {"size": "middle"}}, "key": "file_name", "title": "复制后文件名", "name": "file_name", "tip": "指定复制后文件名，无需输入文件扩展名，为空默认使用原文件名称", "default": "", "required": false}, {"types": "OptionType", "formType": {"type": "SELECT"}, "key": "copy_options", "title": "文件存在时", "name": "copy_options", "tip": "选择指定目录下文件已存在时的操作； 生成副本:将在文件名称后增加数字标识，如a(1).txt，如果副本文件同样存在，则数字递增； 覆盖:删除已存在文件并重新创建； 跳过:返回当前已存在文件路径", "options": [{"label": "覆盖原有文件", "value": "overwrite"}, {"label": "跳过保存操作", "value": "skip"}, {"label": "创建文件副本", "value": "generate"}], "default": "generate", "required": false}], "outputList": [{"types": "Str", "formType": {"type": "RESULT"}, "key": "copy_file_path", "title": "复制后文件路径", "tip": "输出复制后文件路径，并保存至变量，数据类型为字符串"}], "icon": "copy-file", "helpManual": "复制目标文件到指定目录"}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('182','File.file_create','{"key": "File.file_create", "title": "创建文件", "version": "1.0.1", "src": "astronverse.system.file.File().file_create", "comment": "在指定目录 @{dst_path} 下创建文件 @{file_name} ，并保存创建文件路径到 @{new_file_path}", "inputList": [{"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON_FILE", "params": {"filters": [], "file_type": "folder"}}, "key": "dst_path", "title": "指定目录", "name": "dst_path", "tip": "输入或选择指定文件夹目录", "default": "", "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON", "params": {"size": "middle"}}, "key": "file_name", "title": "文件名称", "name": "file_name", "tip": "输入文件名称及扩展名", "default": "", "required": true}, {"types": "OptionType", "formType": {"type": "SELECT"}, "key": "exist_options", "title": "文件存在时", "name": "exist_options", "tip": "选择创建文件已存在时的操作；生成副本:将在文件名称后增加数字标识，如a(1).txt，如果副本文件同样存在，则数字递增；覆盖:删除已存在文件并重新创建；跳过:返回当前已存在文件路径", "options": [{"label": "覆盖原有文件", "value": "overwrite"}, {"label": "跳过保存操作", "value": "skip"}, {"label": "创建文件副本", "value": "generate"}], "default": "generate", "required": false}], "outputList": [{"types": "Str", "formType": {"type": "RESULT"}, "key": "new_file_path", "title": "创建文件路径", "tip": "输出创建文件路径，并保存到变量中，数据类型为字符串"}], "icon": "create-new-file", "helpManual": "在指定目录下创建文件"}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('183','File.file_delete','{"key": "File.file_delete", "title": "删除文件", "version": "1.0.1", "src": "astronverse.system.file.File().file_delete", "comment": "删除文件 @{file_path} ，并将结果输出至变量 @{delete_file_result}", "inputList": [{"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON_FILE", "params": {"filters": [], "file_type": "file"}}, "key": "file_path", "title": "待删除文件", "name": "file_path", "tip": "选择或输入待删除文件路径", "default": "", "required": true}, {"types": "DeleteType", "formType": {"type": "RADIO"}, "key": "delete_options", "title": "删除操作", "name": "delete_options", "tip": "选择将文件彻底删除或移入回收站", "options": [{"label": "彻底删除", "value": "delete"}, {"label": "移入回收站", "value": "trash"}], "default": "delete", "required": false}], "outputList": [{"types": "Str", "formType": {"type": "RESULT"}, "key": "delete_file_result", "title": "输出删除结果至", "tip": "将文件删除结果保存至变量，数据类型为布尔值"}], "icon": "delete-file", "helpManual": "删除指定文件，并将执行结果输出至变量"}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('184','File.file_exist','{"key": "File.file_exist", "title": "IF文件存在", "version": "1.0.1", "src": "astronverse.system.file.File().file_exist", "comment": "判断文件 @{file_path} 是否存在，存在就执行以下操作", "inputList": [{"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON_FILE", "params": {"filters": [], "file_type": "file"}}, "key": "file_path", "title": "文件路径", "name": "file_path", "tip": "输入或选择文件路径", "default": "", "required": true}, {"types": "ExistType", "formType": {"type": "RADIO"}, "key": "exist_type", "title": "判断类型", "name": "exist_type", "tip": "选择判断类型", "options": [{"label": "存在", "value": "exist"}, {"label": "不存在", "value": "not_exist"}], "default": "exist", "required": false}], "outputList": [], "icon": "check-file-exists", "helpManual": "判断文件是否存在并将判断结果输出至变量"}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('185','File.file_info','{"key": "File.file_info", "title": "获取文件信息", "version": "1.0.1", "src": "astronverse.system.file.File().file_info", "comment": "获取指定文件 @{file_path} 的 @{info_type} 信息，并保存文件信息至变量 @{file_info}", "inputList": [{"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON_FILE", "params": {"file_type": "file"}}, "key": "file_path", "title": "文件路径", "name": "file_path", "tip": "选择或输入文件路径", "default": "", "required": true}, {"types": "InfoType", "formType": {"type": "SELECT"}, "key": "info_type", "title": "获取信息类型", "name": "info_type", "tip": "指定获取的信息类型", "options": [{"label": "全部信息", "value": "all"}, {"label": "绝对路径", "value": "abs_path"}, {"label": "根目录", "value": "root"}, {"label": "文件路径", "value": "directory"}, {"label": "文件大小(字节)", "value": "size"}, {"label": "文件名", "value": "name_ext"}, {"label": "单独文件名", "value": "name"}, {"label": "文件扩展名", "value": "extension"}, {"label": "文件创建时间", "value": "c_time"}, {"label": "文件修改时间", "value": "m_time"}], "default": "all", "required": false}], "outputList": [{"types": "Dict", "formType": {"type": "RESULT"}, "key": "file_info", "title": "文件信息为", "tip": "输出文件信息至变量，获取全部信息时数据类型为字典，获取其他信息时数据类型为字符串"}], "icon": "get-file-info", "helpManual": "获取文件的全部信息/大小/文件路径/大小(字节)/根目录/文件夹目录/名称与扩展名/名称/扩展名/创建时间/修改时间，并保存到输出变量"}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('186','File.file_move','{"key": "File.file_move", "title": "移动文件", "version": "1.0.1", "src": "astronverse.system.file.File().file_move", "comment": "将文件 @{file_path} 移动至指定目录 @{target_folder} 下，并保存移动后的文件路径 @{move_file_path}", "inputList": [{"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON_FILE", "params": {"filters": [], "file_type": "file"}}, "key": "file_path", "title": "待移动文件路径", "name": "file_path", "tip": "选择或输入待移动文件路径", "default": "", "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON_FILE", "params": {"filters": [], "file_type": "folder"}}, "key": "target_folder", "title": "指定目录", "name": "target_folder", "tip": "选择或输入目标目录， 指定目录不存在时默认自动创建", "default": "", "required": true}, {"types": "StateType", "formType": {"type": "RADIO"}, "key": "state_type", "title": "目录不存在时", "name": "state_type", "tip": "设置指定目录不存在时执行的操作", "options": [{"label": "创建", "value": "create"}, {"label": "提示并报错", "value": "error"}], "default": "error", "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "file_name", "title": "移动后文件名", "name": "file_name", "tip": "输入移动后文件名(不需后缀名)，默认为空使用原文件名", "default": "", "required": false}, {"types": "OptionType", "formType": {"type": "SELECT"}, "key": "exist_options", "title": "文件存在时", "name": "exist_options", "tip": "选择文件存在时执行的操作（覆盖、跳过、生成副本）", "options": [{"label": "覆盖原有文件", "value": "overwrite"}, {"label": "跳过保存操作", "value": "skip"}, {"label": "创建文件副本", "value": "generate"}], "default": "generate", "required": false}], "outputList": [{"types": "Str", "formType": {"type": "RESULT"}, "key": "move_file_path", "title": "移动后文件路径", "tip": "输出移动后文件路径至变量，数据类型为字符串"}], "icon": "move-file", "helpManual": "将指定文件移动到目标目录，并输出移动后的文件路径至变量"}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('187','File.file_read','{"key": "File.file_read", "title": "读取文件", "version": "1.0.1", "src": "astronverse.system.file.File().file_read", "comment": "按照 @{read_type} 方式读取文件 @{file_path} 中的内容，并保存至变量 @{read_file_content}", "inputList": [{"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON_FILE", "params": {"filters": [], "file_type": "file"}}, "key": "file_path", "title": "待读取文件路径", "name": "file_path", "tip": "选择或输入待读取文件路径， 支持读取的文件类型有：\\".txt\\"， \\".docx\\"， \\".md\\"， \\".py\\"， \\".json\\"， \\".csv\\"", "default": "", "required": true}, {"types": "ReadType", "formType": {"type": "SELECT"}, "key": "read_type", "title": "读取方式", "name": "read_type", "tip": "选择读取方式，全部读取:读取全部内容； 按行读取:按行读取文本内容； 二进制:以二进制方式读取文件内容", "options": [{"label": "读取全部内容", "value": "all"}, {"label": "按行读取到列表中", "value": "list"}, {"label": "二进制方式读取", "value": "byte"}], "default": "all", "required": false}, {"types": "EncodeType", "formType": {"type": "SELECT"}, "key": "encode_type", "title": "编码方式", "name": "encode_type", "tip": "选择读取内容的编码方式，默认选项时自动使用待读取文件的编码方式", "options": [{"label": "默认", "value": "default"}, {"label": "ansi", "value": "ansi"}, {"label": "utf-8", "value": "utf-8"}, {"label": "utf-16", "value": "utf-16"}, {"label": "utf-16 be", "value": "utf-16 be"}, {"label": "gbk", "value": "gbk"}, {"label": "gb2312", "value": "gb2312"}, {"label": "gb18030", "value": "gb18030"}], "default": "default", "required": false}], "outputList": [{"types": "Any", "formType": {"type": "RESULT"}, "key": "read_file_content", "title": "读取内容为", "tip": "输出读取内容至变量，数据类型为字符串"}], "icon": "read-file", "helpManual": "读取指定文件内容，并将读取内容输出保存至变量"}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('188','File.file_rename','{"key": "File.file_rename", "title": "重命名文件", "version": "1.0.1", "src": "astronverse.system.file.File().file_rename", "comment": "将文件 @{file_path} 重命名为 @{new_name} 并保存重命名后的文件路径 @{rename_file_path}", "inputList": [{"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON_FILE", "params": {"filters": [], "file_type": "file"}}, "key": "file_path", "title": "待重命名文件路径", "name": "file_path", "tip": "选择或输入待重命名文件路径", "default": "", "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "new_name", "title": "新文件名", "name": "new_name", "tip": "输入新文件名(不需后缀名)", "default": "", "required": true}, {"types": "OptionType", "formType": {"type": "SELECT"}, "key": "exist_options", "title": "文件存在时", "name": "exist_options", "tip": "选择文件存在时执行的操作（覆盖、跳过、生成副本）", "options": [{"label": "覆盖原有文件", "value": "overwrite"}, {"label": "跳过保存操作", "value": "skip"}, {"label": "创建文件副本", "value": "generate"}], "default": "generate", "required": false}], "outputList": [{"types": "Str", "formType": {"type": "RESULT"}, "key": "rename_file_path", "title": "重命名后文件路径", "tip": "输出重命名后文件路径至变量，数据类型为字符串"}], "icon": "rename-file", "helpManual": "将指定文件重命名，并输出重命名后的文件路径至变量"}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('189','File.file_search','{"key": "File.file_search", "title": "查找文件", "version": "1.0.1", "src": "astronverse.system.file.File().file_search", "comment": "在 @{folder_path} 目录中查找文件名包含 @{search_pattern} 的文件，并保存匹配文件路径至变量 @{find_file_result}", "inputList": [{"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON_FILE", "params": {"filters": [], "file_type": "folder"}}, "key": "folder_path", "title": "待查找文件所在目录", "name": "folder_path", "tip": "选择或输入待查找文件所在目录", "default": "", "required": true}, {"types": "SearchType", "formType": {"type": "RADIO"}, "key": "find_type", "title": "查找方式", "name": "find_type", "tip": "指定查找方式：精确匹配需输入完整文件名；模糊匹配输入部分文件名，需区分大小写；正则表达式匹配输入正则表达式", "options": [{"label": "精确匹配", "value": "exact"}, {"label": "模糊匹配", "value": "fuzzy"}, {"label": "正则表达式匹配", "value": "regex"}], "default": "fuzzy", "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "search_pattern", "title": "查找文件名", "name": "search_pattern", "tip": "输入查找内容", "default": "", "required": true}, {"types": "TraverseType", "formType": {"type": "RADIO"}, "key": "traverse_subfolder", "title": "遍历子文件夹", "name": "traverse_subfolder", "tip": "选择是否遍历子文件夹", "options": [{"label": "遍历子目录", "value": "yes"}, {"label": "不遍历子目录", "value": "no"}], "default": "no", "required": false}], "outputList": [{"types": "List", "formType": {"type": "RESULT"}, "key": "find_file_result", "title": "保存查找结果至", "tip": "输出匹配文件路径列表，并保存到变量，数据类型为列表"}], "icon": "find-file", "helpManual": "在指定目录中查找文件名包含指定内容的文件，并输出文件列表至变量"}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('190','File.file_wait_status','{"key": "File.file_wait_status", "title": "等待文件", "version": "1.0.1", "src": "astronverse.system.file.File().file_wait_status", "comment": "等待文件 @{file_path} 状态为 @{status_type} 时执行下一步，保存等待结果到 @{wait_file_result}", "inputList": [{"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON_FILE", "params": {"filters": [], "file_type": "file"}}, "key": "file_path", "title": "文件路径", "name": "file_path", "tip": "选择或输入文件路径", "default": "", "required": true}, {"types": "StatusType", "formType": {"type": "RADIO"}, "key": "status_type", "title": "等待状态", "name": "status_type", "tip": "选择等待文件的状态", "options": [{"label": "被创建", "value": "created"}, {"label": "被删除", "value": "deleted"}], "default": "created", "required": false}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "wait_time", "title": "超时时间", "name": "wait_time", "tip": "设置等待超时时间，单位为秒", "default": 10, "value": [{"type": "str", "value": ""}], "required": false}], "outputList": [{"types": "Str", "formType": {"type": "RESULT"}, "key": "wait_file_result", "title": "保存等待结果至", "tip": "输出等待结果至变量，数据类型为布尔值"}], "icon": "wait-file", "helpManual": "等待文件状态为指定状态时执行下一步，并输出等待结果至变量"}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
