th", "title": "文件路径", "tip": "输出写入后文件路径至变量，数据类型为字符串"}], "icon": "write-file", "helpManual": "向指定文件中写入内容，并输出写入后的文件路径至变量"}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('192','File.get_file_encoding_type','{"key": "File.get_file_encoding_type", "title": "获取文件编码类型", "version": "1.0.1", "src": "astronverse.system.file.File().get_file_encoding_type", "comment": "获取文件 @{file_path} 的编码类型并保存至变量 @{file_encoding_type}", "inputList": [{"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON_FILE", "params": {"filters": [], "file_type": "file"}}, "key": "file_path", "title": "文件路径", "name": "file_path", "tip": "选择或输入待获取编码类型的文件路径", "default": "", "required": true}], "outputList": [{"types": "Str", "formType": {"type": "RESULT"}, "key": "file_encoding_type", "title": "文件编码类型", "tip": "输出文件编码类型至变量，数据类型为字符串"}], "icon": "get-file-encoding", "helpManual": "获取指定文件的编码类型，并输出编码类型至变量"}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:16');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('193','File.get_file_list','{"key": "File.get_file_list", "title": "获取文件列表", "version": "1.0.1", "src": "astronverse.system.file.File().get_file_list", "comment": "获取指定目录 @{folder_path} 中的文件列表，并保存文件列表至变量 @{file_list}", "inputList": [{"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON_FILE", "params": {"filters": [], "file_type": "folder"}}, "key": "folder_path", "title": "文件目录", "name": "folder_path", "tip": "选择或输入文件目录路径", "default": "", "required": true}, {"types": "TraverseType", "formType": {"type": "RADIO"}, "key": "traverse_subfolder", "title": "遍历子目录", "name": "traverse_subfolder", "tip": "选择是否遍历子目录", "options": [{"label": "遍历子目录", "value": "yes"}, {"label": "不遍历子目录", "value": "no"}], "default": "no", "required": true}, {"types": "Bool", "formType": {"type": "SWITCH", "params": {}}, "key": "tempfile_include", "title": "是否包含临时文件", "name": "tempfile_include", "tip": "选择是否包含临时文件，例如~,~$开头或.tmp结尾的文件", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": true, "required": true}, {"types": "OutputType", "formType": {"type": "RADIO"}, "key": "output_type", "title": "输出方式", "name": "output_type", "tip": "设置输出方式", "options": [{"label": "列表输出", "value": "list"}, {"label": "存储到表格文件", "value": "excel"}], "default": "list", "required": false}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON_FILE", "params": {"filters": [], "file_type": "folder"}}, "key": "excel_path", "title": "Excel保存目录", "name": "excel_path", "tip": "选择或输入保存的Excel保存目录", "default": "", "dynamics": [{"key": "$this.excel_path.show", "expression": "return $this.output_type.value == ''excel''"}], "required": true}, {"types": "StateType", "formType": {"type": "RADIO"}, "key": "state_type", "title": "目录不存在时", "name": "state_type", "tip": "选择Excel保存目录不存在时执行的操作", "options": [{"label": "创建", "value": "create"}, {"label": "提示并报错", "value": "error"}], "defa