INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('205','Gui.mouse','{"key": "Gui.mouse", "title": "鼠标点击", "version": "1.0.1", "src": "astronverse.input.gui_mouse.GuiMouse().mouse", "comment": "模拟鼠标(@{btn_type:左键/右键/中键}) (@{btn_model:按下/弹起/单机/双击}))", "inputList": [{"types": "BtnType", "formType": {"type": "RADIO"}, "key": "btn_type", "title": "鼠标按键", "name": "btn_type", "tip": "选择点击鼠标上的键位", "options": [{"label": "左键", "value": "left"}, {"label": "中键", "value": "middle"}, {"label": "右键", "value": "right"}], "default": "left", "required": true}, {"types": "BtnModel", "formType": {"type": "SELECT"}, "key": "btn_model", "title": "点击方式", "name": "btn_model", "tip": "选择操作鼠标的点击方式", "options": [{"label": "单击", "value": "click"}, {"label": "双击", "value": "double_click"}, {"label": "按下", "value": "down"}, {"label": "弹起", "value": "up"}], "default": "click", "required": true}, {"types": "ControlType", "formType": {"type": "SELECT"}, "key": "ctrl_type", "title": "键盘辅助按键", "name": "ctrl_type", "tip": "选择键盘辅助按键，默认为无", "options": [{"label": "无", "value": "none"}, {"label": "ctrl", "value": "ctrl"}, {"label": "alt", "value": "alt"}, {"label": "shift", "value": "shift"}, {"label": "win", "value": "win"}, {"label": "space", "value": "space"}], "default": "none", "level": "advanced", "required": true}, {"types": "ClickMoveType", "formType": {"type": "RADIO"}, "key": "click_move_type", "title": "点击前移动鼠标", "name": "click_move_type", "tip": "点击前将鼠标移动到指定位置，默认在当前位置点击", "options": [{"label": "当前位置点击", "value": "current"}, {"label": "移动到屏幕指定位置", "value": "screen"}, {"label": "移动到激活窗口内指定位置", "value": "active_window"}], "default": "current", "required": false}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "click_x", "title": "点击位置横坐标x", "name": "click_x", "tip": "移动到屏幕/激活窗口内指定位置时填写", "default": 0, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.click_x.show", "expression": "return [''screen'