INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('225','MathProcess.calculate_expression','{"key": "MathProcess.calculate_expression", "title": "数学计算", "version": "1.0.2", "src": "astronverse.dataprocess.math.MathProcess().calculate_expression", "comment": "进行基本的数学计算 @{left}  @{operator}  @{right} ，返回计算结果 @{calculation_number}", "inputList": [{"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "left", "title": "运算符左侧值", "name": "left", "tip": "", "default": "", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "MathOperatorType", "formType": {"type": "SELECT"}, "key": "operator", "title": "运算符", "name": "operator", "tip": "", "options": [{"label": "加", "value": "+"}, {"label": "减", "value": "-"}, {"label": "乘", "value": "*"}, {"label": "除", "value": "/"}], "default": "+", "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "right", "title": "运算符右侧值", "name": "right", "tip": "", "default": "", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "MathRoundType", "formType": {"type": "SELECT"}, "key": "handle_method", "title": "返回值处理方式", "name": "handle_method", "tip": "", "options": [{"label": "四舍五入", "value": "round"}, {"label": "向上取整", "value": "ceil"}, {"label": "向下取整", "value": "floor"}, {"label": "不做操作", "value": "none"}], "default": "none", "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "precision", "title": "四舍五入保留位数", "name": "precision", "tip": "", "default": 0, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.precision.show", "expression": "return $this.handle_method.value == ''round''"}], "required": true}], "outputList": [{"types": "Any", "formType": {"type": "RESULT"}, "key": "calculation_number", "title": "计算结果", "tip": ""}], "icon": "math-calculation", "helpManual": ""}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:17');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('226','MathProcess.generate_random_number','{"key": "MathProcess.generate_random_number", "title": "生成随机数", "version": "1.0.2", "src": "astronverse.dataprocess.math.MathProcess().generate_random_number", "comment": "生成 @{number_type} 类型 @{size} 个随机数，范围为 @{start} 到 @{end} ，返回生成的随机数 @{generated_random_numbers}", "inputList": [{"types": "NumberType", "formType": {"type": "RADIO"}, "key": "number_type", "title": "随机数类型", "name": "number_type", "tip": "", "options": [{"label": "整数", "value": "integer"}, {"label": "浮点数", "value": "float"}], "default": "integer", "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "size", "title": "随机数个数", "name": "size", "tip": "", "default": 1, "value": [{"type": "str", "value": ""}], "required": false}, {"types": "Float", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "start", "title": "开始范围", "name": "start", "tip": "", "default": 0, "value": [{"type": "str", "value": ""}], "required": true}, {"types": "Float", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "end", "title": "结束范围", "name": "end", "tip": "", "default": 101, "value": [{"type": "str", "value": ""}], "required": true}], "outputList": [{"types": "Any", "formType": {"type": "RESULT"}, "key": "generated_random_numbers", "title": "生成的随机数", "tip": ""}], "icon": "generate-random-number", "helpManual": ""}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:17');
