INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('231','Network.create_folder','{"key": "Network.create_folder", "title": "创建文件夹(FTP)", "version": "1.0.1", "src": "astronverse.network.ftp.FTP().create_folder", "comment": "在指定FTP连接(@{ftp_instance})下创建文件夹(@{folder_name}),并保存新文件夹路径到(@{new_folder})中", "inputList": [{"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "ftp_instance", "title": "FTP连接对象", "name": "ftp_instance", "tip": "需要创建文件夹的FTP连接对象", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "folder_name", "title": "新文件夹名称", "name": "folder_name", "tip": "需要创建的文件夹名称", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "FileExistenceType", "formType": {"type": "SELECT"}, "key": "exist_type", "title": "文件夹存在时", "name": "exist_type", "tip": "当FTP连接下存在同名文件夹时需要执行的操作", "options": [{"label": "创建文件副本", "value": "rename"}, {"label": "覆盖原有文件", "value": "overwrite"}, {"label": "跳过保存操作", "value": "cancel"}], "default": "rename", "required": false}], "outputList": [{"types": "Str", "formType": {"type": "RESULT"}, "key": "new_folder", "title": "创建后文件夹路径", "tip": "将创建后的文件夹路径保存至变量"}], "icon": "create-folder", "helpManual": "在指定FTP连接下创建文件夹"}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:17');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('232','Network.ftp_close','{"key": "Network.ftp_close", "title": "关闭FTP连接", "version": "1.0.1", "src": "astronverse.network.ftp.FTP().ftp_close", "comment": "断开与(@{ftp_instance})的FTP连接，并将结果输出至变量(@{close_ftp})", "inputList": [{"types": "Any", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "ftp_instance", "title": "FTP对象", "name": "ftp_instance", "tip": "待断开的FTP连接对象", "value": [{"type": "str", "value": ""}], "required": true}], "outputList": [{"types": "Bool", "formType": {"type": "RESULT"}, "key": "close_ftp", "title": "断开结果保存至", "tip": "FTP连接是否成功断开的布尔值"}], "icon": "ftp-close-connection", "helpManual": "断开一个FTP连接，并返回断开结果"}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:17');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('233','Network.ftp_create','{"key": "Network.ftp_create", "title": "创建FTP连接", "version": "1.0.1", "src": "astronverse.network.ftp.FTP().ftp_create", "comment": "建立与地址(@{host}),端口(@{port})的(@{server_type})连接，输出为(@{ftp_instance})", "inputList": [{"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "host", "title": "服务器地址", "name": "host", "tip": "FTP/SFTP服务器地址", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "port", "title": "服务器端口号", "name": "port", "tip": "FTP常用21，SFTP常用22", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "name", "title": "用户名", "name": "name", "tip": "文件服务器提供的可登录账号", "value": [{"type": "str", "value": ""}], "required": false}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "password", "title": "用户密码", "name": "password", "tip": "文件服务器提供的可登录账号的密码；SFTP密钥连接时为密钥口令，可为空", "value": [{"type": "str", "value": ""}], "required": false}, {"types": "FtpServerType", "formType": {"type": "RADIO"}, "key": "server_type", "title": "服务器类型", "name": "server_type", "tip": "选择FTP或SFTP服务器", "options": [{"label": "FTP服务器", "value": "ftp"}, {"label": "SFTP服务器", "value": "sftp"}], "default": "ftp", "required": false}, {"types": "SftpLoginMode", "formType": {"type": "RADIO"}, "key": "login_mode", "title": "SFTP登录方式", "name": "login_mode", "tip": "密码连接或密钥连接（仅SFTP有效）", "options": [{"label": "密码连接", "value": "password"}, {"label": "密钥连接", "value": "key"}], "default": "password", "required": false}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON_FILE", "params": {"filters": [], "file_type": "file"}}, "key": "key_path", "title": "私钥文件路径", "name": "key_path", "tip": "SFTP密钥连接时必填的私钥文件路径", "default": "", "dynamics": [{"key": "$this.key_path.show", "expression": "return $this.server_type.value == ''sftp'' && $this.login_mode.value == ''key''"}], "required": false}], "outputList": [{"types": "Str", "formType": {"type": "RESULT"}, "key": "ftp_instance", "title": "保存FTP连接对象至", "tip": "将创建的FTP/SFTP连接对象保存至指定变量中"}], "icon": "ftp-create-connection", "helpManual": "建立一个文件服务器的FTP/SFTP连接，并返回连接对象；SFTP支持密码连接与密钥连接两种方式"}',NULL,'2026-08-16 12:43:56','2026-08-16 12:43:56');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('234','Network.ftp_delete','{"key": "Network.ftp_delete", "title": "删除文件/文件夹(FTP)", "version": "1.0.1", "src": "astronverse.network.ftp.FTP().ftp_delete", "comment": "删除(@{ftp_instance})上(@{delete_file_name||delete_folder_name}),并输出删除结果至变量(@{delete_ftp_result})", "inputList": [{"types": "Any", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "ftp_instance", "title": "FTP连接对象", "name": "ftp_instance", "tip": "执行文件/文件夹删除操作的FTP连接对象", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "FileType", "formType": {"type": "RADIO"}, "key": "file_type", "title": "删除对象", "name": "file_type", "tip": "", "options": [{"label": "文件", "value": "file"}, {"label": "文件夹", "value": "folder"}], "default": "file", "required": false}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "delete_file_name", "title": "待删除文件", "name": "delete_file_name", "tip": "支持单个或多个文件删除,多个文件名之间使用逗号隔开,如:test1.txt,test2.txt,test3.txt", "default": "", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.delete_file_name.show", "expression": "return $this.file_type.value == ''file''"}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "delete_folder_name", "title": "待删除文件夹", "name": "delete_folder_name", "tip": "支持单个或多个文件夹删除,多个文件夹之间用逗号隔开,如:folder1,folder2,folder3", "default": "", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.delete_folder_name.show", "expression": "return $this.file_type.value == ''folder''"}], "required": true}], "outputList": [{"types": "Bool", "formType": {"type": "RESULT"}, "key": "delete_ftp_result", "title": "删除结果", "tip": "输出删除结果到变量,数据类型为布尔值"}], "icon": "delete-folder-ftp", "helpManual": "删除FTP服务器中指定文件/文件夹"}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:17');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('235','Network.ftp_download','{"key": "Network.ftp_download", "title": "下载文件/文件夹(FTP)", "version": "1.0.1", "src": "astronverse.network.ftp.FTP().ftp_download", "comment": "下载(@{download_file_name||download_folder_name})至本地目录(@{dst_path}),并将下载后路径保存到变量(@{download_ftp_path})", "inputList": [{"types": "Any", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "ftp_instance", "title": "FTP连接对象", "name": "ftp_instance", "tip": "执行下载文件/文件夹的FTP服务器连接对象", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "FileType", "formType": {"type": "RADIO"}, "key": "file_type", "title": "下载对象", "name": "file_type", "tip": "", "options": [{"label": "文件", "value": "file"}, {"label": "文件夹", "value": "folder"}], "default": "file", "required": false}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "download_file_name", "title": "待下载文件", "name": "download_file_name", "tip": "支持单个或多个文件下载,多个文件名之间用逗号隔开,如:test1.txt,test2.txt,test3.txt", "default": "", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.download_file_name.show", "expression": "return $this.file_type.value == ''file''"}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "download_folder_name", "title": "待下载文件夹", "name": "download_folder_name", "tip": "支持单个或多个文件夹下载,多个文件夹之间用逗号隔开,如:folder1,folder2,folder3", "default": "", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.download_folder_name.show", "expression": "return $this.file_type.value == ''folder''"}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON_FILE", "params": {"filters": [], "file_type": "folder"}}, "key": "dst_path", "title": "下载至", "name": "dst_path", "tip": "本地存储路径", "default": "", "required": true}, {"types": "StateType", "formType": {"type": "RADIO"}, "key": "state_type", "title": "本地路径不存在时", "name": "state_type", "tip": "当本地存储路径不存在时执行的操作", "options": [{"label": "创建", "value": "create"}, {"label": "提示并报错", "value": "error"}], "default": "create", "required": false}, {"types": "FileExistenceType", "formType": {"type": "SELECT"}, "key": "exist_type", "title": "下载对象存在时", "name": "exist_type", "tip": "下载文件/文件夹存在时执行的操作", "options": [{"label": "创建文件副本", "value": "rename"}, {"label": "覆盖原有文件", "value": "overwrite"}, {"label": "跳过保存操作", "value": "cancel"}], "default": "rename", "required": false}], "outputList": [{"types": "List", "formType": {"type": "RESULT"}, "key": "download_ftp_path", "title": "下载列表", "tip": "输出已下载的文件/文件夹路径列表至变量,数据类型为列表"}], "icon": "download-folder", "helpManual": "将FTP服务器上的多个文件/文件夹下载至本地"}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:17');
