ey": "new_folder_name", "title": "新文件夹名称", "name": "new_folder_name", "tip": "输入新文件夹名称", "default": "", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.new_folder_name.show", "expression": "return $this.file_type.value == ''folder''"}], "required": true}, {"types": "FileExistenceType", "formType": {"type": "SELECT"}, "key": "exist_type", "title": "重命名对象存在时", "name": "exist_type", "tip": "重命名后对象已存在时执行的操作", "options": [{"label": "创建文件副本", "value": "rename"}, {"label": "覆盖原有文件", "value": "overwrite"}, {"label": "跳过保存操作", "value": "cancel"}], "default": "rename", "required": false}], "outputList": [{"types": "Str", "formType": {"type": "RESULT"}, "key": "rename_ftp_path", "title": "重命名后路径", "tip": "保存重命名后(@{file_type})路径至变量"}], "icon": "rename-folder", "helpManual": "重命名FTP服务器上文件/文件夹"}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:17');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('237','Network.ftp_upload','{"key": "Network.ftp_upload", "title": "上传文件/文件夹(FTP)", "version": "1.0.1", "src": "astronverse.network.ftp.FTP().ftp_upload", "comment": "上传(@{file_path||folder_path})至FTP指定目录(@{ftp_pwd}),并将上传后路径结果保存到(@{upload_ftp_list})中", "inputList": [{"types": "Any", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "ftp_instance", "title": "FTP连接对象", "name": "ftp_instance", "tip": "需要上传文件/文件夹的FTP连接对象", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "FileType", "formType": {"type": "RADIO"}, "key": "file_type", "title": "上传对象", "name": "file_type", "tip": "", "options": [{"label": "文件", "value": "file"}, {"label": "文件夹", "value": "folder"}], "default": "file", "required": false}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "ftp_pwd", "title": "远程工作目录", "name": "ftp_pwd", "tip": "文件/文件夹上传的远程工作目录,默认为空,上传至当前工作路径", "default": "", "value": [{"type": "str", "value": ""}], "required": false}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON_FILE", "params": {"filters": [], "file_type": "files"}}, "key": "file_path", "title": "待上传文件", "name": "file_path", "tip": "支持单个或多个文件上传,多个文件名之间用逗号隔开,如:test1.txt,test2.txt,test3.txt", "default": "", "dynamics": [{"key": "$this.file_path.show", "expression": "return $this.file_type.value == ''file''"}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON_FILE", "params": {"filters": [], "file_type": "folder"}}, "key": "folder_path", "title": "待上传文件夹", "name": "folder_path", "tip": "支持单个或多个文件夹上传,多个文件夹之间用逗号隔开,如:folder1,folder2,folder3", "default": "", "dynamics": [{"key": "$this.folder_path.show", "expression": "return $this.file_type.value == ''folder''"}], "required": true}, {"types": "FileExistenceType", "formType": {"type": "SELECT"}, "key": "exist_type", "title": "上传对象已存在时", "name": "exist_type", "tip": "要上传的文件/文件夹在FTP服务器上