INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('240','Network.http_download','{"key": "Network.http_download", "title": "HTTP下载", "version": "1.0.1", "src": "astronverse.network.network.Network().http_download", "comment": "HTTP下载", "inputList": [{"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "url", "title": "下载地址", "name": "url", "tip": "", "default": "", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON_FILE", "params": {"filters": [], "file_type": "folder"}}, "key": "dst_dir", "title": "文件保存目录", "name": "dst_dir", "tip": "", "default": "", "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "rename", "title": "指定文件名", "name": "rename", "tip": "不指定自动沿用下载路径中的默认文件名，没有默认文件名则报错", "default": "", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.rename.show", "expression": "return $this.state_type.value == ''create''"}], "required": false}, {"types": "StateType", "formType": {"type": "RADIO"}, "key": "state_type", "title": "目录不存在时", "name": "state_type", "tip": "设置文件保存目录不存在时的处理方式", "options": [{"label": "创建", "value": "create"}, {"label": "提示并报错", "value": "error"}], "default": "create", "required": false}, {"types": "FileExistenceType", "formType": {"type": "SELECT"}, "key": "exist_type", "title": "文件存在时", "name": "exist_type", "tip": "设置目标文件已存在时的处理方式", "options": [{"label": "创建文件副本", "value": "rename"}, {"label": "覆盖原有文件", "value": "overwrite"}, {"label": "跳过保存操作", "value": "cancel"}], "default": "rename", "required": false}], "outputList": [{"types": "Str", "formType": {"type": "RESULT"}, "key": "http_download_path", "title": "下载文件保存到", "tip": "将下载文件路径保存到变量中"}], "icon": "http-download", "helpManual": "下载指定URL(@{url})的文件保存到指定目录(@{dst_dir})中,并保存下载路径到变量(@{http_download_path})"}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:17');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('241','Network.http_request','{"key": "Network.http_request", "title": "HTTP请求", "version": "1.0.1", "src": "astronverse.network.network.Network().http_request", "comment": "向URL(@{url})发送HTTP请求(@{request_type}), 请求头(@{headers}), 请求体(@{body}), 并保存响应结果到{@{http_response}}", "inputList": [{"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "url", "title": "URL", "name": "url", "tip": "", "default": "", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "RequestType", "formType": {"type": "SELECT"}, "key": "request_type", "title": "请求类型", "name": "request_type", "tip": "", "options": [{"label": "post", "value": "post"}, {"label": "get", "value": "get"}, {"label": "connect", "value": "connect"}, {"label": "put", "value": "put"}, {"label": "patch", "value": "patch"}, {"label": "delete", "value": "delete"}, {"label": "options", "value": "options"}, {"label": "head", "value": "head"}, {"label": "trace", "value": "trace"}], "default": "post", "required": true}, {"types": "Str", "formType": {"type": "INPUT_PYTHON_TEXTAREAMODAL_VARIABLE"}, "key": "curl_text", "title": "curl报文智能识别", "name": "curl_text", "tip": "粘贴浏览器「Copy as cURL」/Fiddler/Postman导出的curl命令，自动解析填充URL/请求类型/请求头/请求体，手动填写的项优先", "default": "", "required": false}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "headers", "title": "请求头", "name": "headers", "tip": "", "default": "", "value": [{"type": "str", "value": ""}], "required": false}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "body", "title": "请求体", "name": "body", "tip": "", "default": "", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.body.show", "expression": "return [''post'', ''put''].includes($this.request_type.value)"}], "required": false}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON_FILE", "params": {"filters": [], "file_t