INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('274','System.compress','{"key": "System.compress", "title": "压缩", "version": "1.0.1", "src": "astronverse.system.compress.Compress().compress", "comment": "压缩 @{file_type} 到指定目录 @{compress_dir} 中，并保存压缩包路径至 @{compress_path}", "inputList": [{"types": "FileFolderType", "formType": {"type": "RADIO"}, "key": "file_type", "title": "选择压缩方式", "name": "file_type", "tip": "选择压缩文件/文件夹/文件和文件夹", "options": [{"label": "文件", "value": "file"}, {"label": "文件夹", "value": "folder"}, {"label": "文件和文件夹", "value": "both"}], "default": "file", "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON_FILE", "params": {"filters": [], "file_type": "files"}}, "key": "file_path", "title": "待压缩文件", "name": "file_path", "tip": "选择或输入待压缩文件路径", "default": "", "dynamics": [{"key": "$this.file_path.show", "expression": "return $this.file_type.value != ''folder''"}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON_FILE", "params": {"filters": [], "file_type": "folder"}}, "key": "folder_path", "title": "待压缩文件夹", "name": "folder_path", "tip": "选择或输入待压缩文件夹路径", "default": "", "dynamics": [{"key": "$this.folder_path.show", "expression": "return $this.file_type.value != ''file''"}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON_FILE", "params": {"filters": [], "file_type": "folder"}}, "key": "compress_dir", "title": "目标路径", "name": "compress_dir", "tip": "保存目标压缩文件路径", "default": "", "required": true}, {"types": "StateType", "formType": {"type": "RADIO"}, "key": "state_type", "title": "目标路径不存在时", "name": "state_type", "tip": "选择目标路径不存在时执行的操作", "options": [{"label": "创建", "value": "create"}, {"label": "提示并报错", "value": "error"}], "default": "error", "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "compress_name", "title": "压缩包名称", "name": "compress_name", "tip": "指定压缩包名称，为空