INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('275','System.copy_clip','{"key": "System.copy_clip", "title": "复制到剪切板", "version": "1.0.1", "src": "astronverse.system.clipboard.Clipboard().copy_clip", "comment": "将 @{content_type}  @{message||file_path||folder_path} 复制到剪切板", "inputList": [{"types": "ContentType", "formType": {"type": "SELECT"}, "key": "content_type", "title": "复制类型", "name": "content_type", "tip": "选择复制到剪贴板的内容类型", "options": [{"label": "文本内容", "value": "msg"}, {"label": "HTML格式文本内容", "value": "html"}, {"label": "文件", "value": "file"}, {"label": "文件夹", "value": "folder"}], "default": "msg", "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "message", "title": "待复制的文本内容", "name": "message", "tip": "输入文本内容", "default": "", "dynamics": [{"key": "$this.message.show", "expression": "return $this.content_type.value == ''msg''"}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON_FILE", "params": {"filters": [], "file_type": "file"}}, "key": "file_path", "title": "待复制的文件路径", "name": "file_path", "tip": "输入或选择待复制文件", "default": "", "dynamics": [{"key": "$this.file_path.show", "expression": "return $this.content_type.value == ''file''"}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON_FILE", "params": {"filters": [], "file_type": "folder"}}, "key": "folder_path", "title": "待复制的文件夹路径", "name": "folder_path", "tip": "输入或选择待复制文件夹", "default": "", "dynamics": [{"key": "$this.folder_path.show", "expression": "return $this.content_type.value == ''folder''"}], "required": true}], "outputList": [], "icon": "copy-to-clipboard", "helpManual": "支持将文本内容/文件/文件夹复制到剪切板"}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:17');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('276','System.get_pid','{"key": "System.get_pid", "title": "获取进程PID", "version": "1.0.1", "src": "astronverse.system.process.Process().get_pid", "comment": "获取与输入 @{process_name} 匹配的进程PID，并保存至输出变量 @{match_proces_pid}", "inputList": [{"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "process_name", "title": "待匹配内容", "name": "process_name", "tip": "输入待匹配进程内容，精确匹配模式下需输入完整进程名，区分大小写", "default": "", "required": true}, {"types": "SearchType", "formType": {"type": "RADIO"}, "key": "search_type", "title": "匹配方式", "name": "search_type", "tip": "选择匹配方式", "options": [{"label": "精确匹配", "value": "exact"}, {"label": "模糊匹配", "value": "fuzzy"}, {"label": "正则表达式匹配", "value": "regex"}], "default": "exact", "required": false}, {"types": "PidType", "formType": {"type": "RADIO"}, "key": "pid_type", "title": "获取内容", "name": "pid_type", "tip": "指定获取到匹配进程PID的内容", "options": [{"label": "获取全部", "value": "all"}, {"label": "获取一个", "value": "one"}], "default": "all", "required": false}], "outputList": [{"types": "Any", "formType": {"type": "RESULT"}, "key": "match_proces_pid", "title": "输出匹配进程PID至", "tip": "当获取全部匹配PID时输出为列表，获取单个匹配PID时输出为整型"}], "icon": "get-process-pid", "helpManual": "输入待匹配进程名称，支持精确匹配/模糊匹配/正则表达式匹配，可获取单个匹配进程PID或全部匹配进程PID，并输出至变量列表"}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:17');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('277','System.paste_clip','{"key": "System.paste_clip", "title": "获取剪切板", "version": "1.0.1", "src": "astronverse.system.clipboard.Clipboard().paste_clip", "comment": "获取剪切板中的 @{content_type} ，并保存至变量 @{output_content}", "inputList": [{"types": "ContentType", "formType": {"type": "SELECT"}, "key": "content_type", "title": "获取类型", "name": "content_type", "tip": "选择剪切板中要获取的内容类型", "options": [{"label": "文本内容", "value": "msg"}, {"label": "HTML格式文本内容", "value": "html"}, {"label": "文件", "value": "file"}, {"label": "文件夹", "value": "folder"}], "default": "msg", "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON_FILE", "params": {"filters": [], "file_type": "folder"}}, "key": "dst_path", "title": "保存路径", "name": "dst_path", "tip": "请输入或选择保存路径", "default": "", "dynamics": [{"key": "$this.dst_path.show", "expression": "return [''file'', ''folder''].includes($this.content_type.value)"}], "required": true}, {"types": "StateType", "formType": {"type": "RADIO"}, "key": "state_type", "title": "保存路径不存在时", "name": "state_type", "tip": "设置保存路径不存在时执行的操作", "options": [{"label": "创建", "value": "create"}, {"label": "提示并报错", "value": "error"}], "default": "error", "dynamics": [{"key": "$this.state_type.show", "expression": "return [''folder'', ''file''].includes($this.content_type.value)"}], "required": false}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "dst_file_name", "title": "文件保存名称", "name": "dst_file_name", "tip": "输入保存的文件名，不需加文件后缀，为空自动使用原文件名", "default": "", "dynamics": [{"key": "$this.dst_file_name.show", "expression": "return $this.content_type.value == ''file''"}], "required": false}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "dst_folder_name", "title": "文件夹保存名称", "name": "dst_folder_name", "tip": "输入保存的文件夹名称，为空自动使用原文件夹名称", "default": "", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.dst_folder_name.show", "expression": "return $this.content_type.value == ''folder''"}], "required": false}], "outputList": [{"types": "Str", "formType": {"type": "RESULT"}, "key": "output_content", "title": "输出剪切板内容至变量", "tip": "获取文本内容输出为文本变量，获取文件/文件夹输出为路径信息"}], "icon": "get-clipboard", "helpManual": "支持获取剪切板中的文本内容/文件/文件夹，并将文本内容/文件文件夹保存路径保存到指定路径中"}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:17');
