$this.paper_size.value == ''CUSTOM'' && $this.printer_type.value == ''custom''"}], "required": true}, {"types": "Float", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "page_height", "title": "纸张高度", "name": "page_height", "tip": "输入打印纸张高度", "default": "", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.page_height.show", "expression": "return $this.paper_size.value == ''CUSTOM'' && $this.printer_type.value == ''custom''"}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "print_num", "title": "打印份数", "name": "print_num", "tip": "输入打印份数，默认1份", "default": 1, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.print_num.show", "expression": "return $this.printer_type.value == ''custom''"}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "page", "title": "页码范围", "name": "page", "tip": "例如：1,3-5 表示打印第1页和第3页到第5页的内容，留空表示打印全部页码", "default": "", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.page.show", "expression": "return ($this.file_type.value == ''word'' || $this.file_type.value == ''excel'') && $this.printer_type.value == ''custom''"}], "required": false}, {"types": "OrientationType", "formType": {"type": "RADIO"}, "key": "orientation_type", "title": "打印版式", "name": "orientation_type", "tip": "选择打印版式，横向/纵向", "options": [{"label": "水平方向", "value": "horizontal"}, {"label": "垂直方向", "value": "vertical"}], "default": "vertical", "dynamics": [{"key": "$this.orientation_type.show", "expression": "return $this.printer_type.value == ''custom''"}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "scale", "title": "缩放(%)", "name": "scale", "tip": "默认100%，输入缩放比例", "default": 100, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.scale.show", "expression": "return $this.printer_type.value == ''custom''"}], "required": true}, {"types": "MarginType", "formType": {"type": "RADIO"}, "key": "margin_type", "title": "边距（单位毫米）", "name": "margin_type", "tip": "", "options": [{"label": "自定义", "value": "custom"}, {"label": "默认", "value": "default"}], "default": "default", "dynamics": [{"key": "$this.margin_type.show", "expression": "return $this.printer_type.value == ''custom''"}], "required": true}, {"types": "Float", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "left_margin", "title": "左边距", "name": "left_margin", "tip": "", "default": 10, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.left_margin.show", "expression": "return $this.margin_type.value == ''custom'' && $this.printer_type.value == ''custom''"}], "required": true}, {"types": "Float", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "top_margin", "title": "上边距", "name": "top_margin", "tip": "", "default": 9.5, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.top_margin.show", "expression": "return $this.margin_type.value == ''custom'' && $this.printer_type.value == ''custom''"}], "required": true}, {"types": "Float", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "right_margin", "title": "右边距", "name": "right_margin", "tip": "", "default": 10, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.right_margin.show", "expression": "return $this.margin_type.value == ''custom'' && $this.printer_type.value == ''custom''"}], "required": true}, {"types": "Float", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "bottom_margin", "title": "下边距", "name": "bottom_margin", "tip": "", "default": 9.5, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.bottom_margin.show", "expression": "return $this.margin_type.value == ''custom'' && $this.printer_type.value == ''custom''"}], "required": true}], "outputList": [{"types": "List", "formType": {"type": "RESULT"}, "key": "printer_status", "title": "打印结果", "tip": "保存打印结果到输出变量，数据类型为布尔值"}], "icon": "printer-print", "helpManual": "连接指定打印机进行文档打印"}',NULL,