INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('281','System.screen_shot','{"key": "System.screen_shot", "title": "屏幕截图", "version": "1.0.1", "src": "astronverse.system.system.System().screen_shot", "comment": "按 @{screen_type} 方式截图并保存到 @{png_path} ，输出图片保存路径 @{screenshot_path}", "inputList": [{"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON_FILE", "params": {"filters": [], "file_type": "folder"}}, "key": "png_path", "title": "图片保存路径", "name": "png_path", "tip": "输入或选择截图后的文件保存路径", "default": "", "required": true}, {"types": "StateType", "formType": {"type": "RADIO"}, "key": "state_type", "title": "路径不存在时", "name": "state_type", "tip": "选择图片保存文件夹不存在时执行的操作", "options": [{"label": "创建", "value": "create"}, {"label": "提示并报错", "value": "error"}], "default": "error", "required": false}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "png_name", "title": "图片保存名称", "name": "png_name", "tip": "输入截图后的文件名，不需加文件后缀", "default": "", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "ScreenType", "formType": {"type": "RADIO"}, "key": "screen_type", "title": "截图区域", "name": "screen_type", "tip": "指定截图区域", "options": [{"label": "全屏", "value": "full"}, {"label": "选择区域", "value": "region"}], "default": "full", "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "top_left_x", "title": "左上角x坐标", "name": "top_left_x", "tip": "输入截图的矩形区域左上角横坐标，单位为像素px", "default": 0, "dynamics": [{"key": "$this.top_left_x.show", "expression": "return $this.screen_type.value == ''region''"}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "top_left_y", "title": "左上角y坐标", "name": "top_left_y", "tip": "输入截图的矩形区域左上角纵坐标，单位为像素px", "default": 0, "dynamics": [{"key": "$this.top_left_y.show", "expression": "return $this.screen_type.value == ''region''"}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "bottom_right_x", "title": "右下角x坐标", "name": "bottom_right_x", "tip": "输入截图的矩形区域右下角横坐标，单位为像素px", "default": 0, "dynamics": [{"key": "$this.bottom_right_x.show", "expression": "return $this.screen_type.value == ''region''"}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "bottom_right_y", "title": "右下角y坐标", "name": "bottom_right_y", "tip": "输入截图的矩形区域右下角纵坐标，单位为像素px", "default": 0, "dynamics": [{"key": "$this.bottom_right_y.show", "expression": "return $this.screen_type.value == ''region''"}], "required": true}], "outputList": [{"types": "Str", "formType": {"type": "RESULT"}, "key": "screenshot_path", "title": "截图保存路径", "tip": ""}], "icon": "screen-screenshot", "helpManual": "选择屏幕或指定区域进行截屏，并保存到指定路径"}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:17');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('282','System.screen_unlock','{"key": "System.screen_unlock", "title": "屏幕解锁", "version": "1.0.1", "src": "astronverse.system.system.System().screen_unlock", "comment": "通过用户名 @{user_name} 和 @{pwd_type}  @{password_text||password_rsa} 进行系统屏幕解锁，并将操作结果输出至变量 @{screen_unlock_result}", "inputList": [{"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "user_name", "title": "用户名", "name": "user_name", "tip": "待解锁屏幕用户名", "default": "", "value": [{"type": "str", "value": ""}], "required": false}, {"types": "PwdType", "formType": {"type": "RADIO"}, "key": "pwd_type", "title": "解锁类型", "name": "pwd_type", "tip": "待解锁屏幕解锁类型", "options": [{"label": "密钥", "value": "rsa"}, {"label": "密码", "value": "password"}], "default": "password", "required": false}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "password_text", "title": "密码", "name": "password_text", "tip": "待解锁屏幕解锁密码", "default": "", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.password_text.show", "expression": "return $this.pwd_type.value == ''password''"}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "password_rsa", "title": "密钥", "name": "password_rsa", "tip": "待解锁屏幕解锁密钥", "default": "", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.password_rsa.show", "expression": "return $this.pwd_type.value == ''rsa''"}], "required": true}], "outputList": [{"types": "Bool", "formType": {"type": "RESULT"}, "key": "screen_unlock_result", "title": "执行结果", "tip": "输出屏幕解锁的执行结果并保存至变量，数据类型为布尔值"}], "icon": "screen-unlock", "helpManual": "输入用户名和密码进行系统屏幕解锁"}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:17');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('283','System.terminate_process','{"key": "System.terminate_process", "title": "终止进程", "version": "1.0.1", "src": "astronverse.system.process.Process().terminate_process", "comment": "终止指定 @{termination_type} 的进程，并保存执行结果至输出变量 @{termination_process}", "inputList": [{"types": "TerminationType", "formType": {"type": "RADIO"}, "key": "termination_type", "title": "终止方式", "name": "termination_type", "tip": "指定终止方式，通过进程PID/进程名称终止进程", "options": [{"label": "进程PID", "value": "pid"}, {"label": "进程名称", "value": "name"}], "default": "pid", "required": false}, {"types": "Any", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "pid", "title": "进程PID", "name": "pid", "tip": "要终止的进程PID", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.pid.show", "expression": "return $this.termination_type.value == ''pid''"}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "process_name", "title": "进程名称", "name": "process_name", "tip": "要终止的进程名称", "default": "", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.process_name.show", "expression": "return $this.termination_type.value == ''name''"}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "time_out", "title": "超时时间", "name": "time_out", "tip": "指定超时时间，单位为秒", "default": 5, "value": [{"type": "str", "value": ""}], "required": false}], "outputList": [{"types": "Bool", "formType": {"type": "RESULT"}, "key": "termination_process", "title": "保存执行结果至", "tip": "输出执行结果并保存到变量，数据类型为布尔值"}], "icon": "terminate-process", "helpManual": "终止指定PID/名称的进程程序"}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:17');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('284','System.uncompress','{"key": "System.uncompress", "title": "解压", "version": "1.0.1", "src": "astronverse.system.compress.Compress().uncompress", "comment": "将压缩文件 @{source_path} 解压至指定目录 @{target_path} 下，并输出解压后文件所在路径 @{uncompress_path}", "inputList": [{"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON_FILE", "params": {"filters": [], "file_type": "file"}}, "key": "source_path", "title": "压缩包路径", "name": "source_path", "tip": "请选择或输入压缩包路径", "default": "", "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON_FILE", "params": {"filters": [], "file_type": "folder"}}, "key": "target_path", "title": "目标解压目录", "name": "target_path", "tip": "选择或输入解压后文件保存路径", "default": "", "required": true}, {"types": "StateType", "formType": {"type": "RADIO"}, "key": "status_type", "title": "目标目录不存在时", "name": "status_type", "tip": "选择目标目录不存在时执行的操作，默认直接创建", "options": [{"label": "创建", "value": "create"}, {"label": "提示并报错", "value": "error"}], "default": "error", "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "pwd", "title": "解压密码", "name": "pwd", "tip": "", "default": "", "value": [{"type": "str", "value": ""}], "required": false}, {"types": "SaveType", "formType": {"type": "RADIO"}, "key": "save_type", "title": "解压缩后源文件是否保留", "name": "save_type", "tip": "解压后对源文件的操作，默认保留", "options": [{"label": "删除", "value": "delete"}, {"label": "保留", "value": "save"}], "default": "save", "required": false}], "outputList": [{"types": "Str", "formType": {"type": "RESULT"}, "key": "uncompress_path", "title": "输出解压后文件路径", "tip": ""}], "icon": "decompress", "helpManual": "将压缩文件解压至指定路径"}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:17');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('285','TimeProcess.format_datetime','{"key": "TimeProcess.format_datetime", "title": "输出指定格式时间文本", "version": "1.0.2", "src": "astronverse.dataprocess.time.TimeProcess().format_datetime", "comment": "将时间对象 @{time} 按照指定格式 @{format_type} 输出文本 @{format_datetime}", "inputList": [{"types": "Date", "formType": {"type": "INPUT_VARIABLE_PYTHON_DATETIME"}, "key": "time", "title": "时间对象", "name": "time", "tip": "", "required": true}, {"types": "TimeFormatType", "formType": {"type": "SELECT"}, "key": "format_type", "title": "时间格式", "name": "format_type", "tip": "", "options": [{"label": "年-月-日", "value": "%Y-%m-%d"}, {"label": "年-月-日 时:分:秒", "value": "%Y-%m-%d %H:%M:%S"}, {"label": "年-月-日 时:分", "value": "%Y-%m-%d %H:%M"}, {"label": "年/月/日", "value": "%Y/%m/%d"}, {"label": "年/月/日 时:分", "value": "%Y/%m/%d %H:%M"}, {"label": "年/月/日 时:分:秒", "value": "%Y/%m/%d %H:%M:%S"}, {"label": "年月日", "value": "%Y%m%d"}, {"label": "时:分", "value": "%H:%M"}, {"label": "时:分:秒", "value": "%H:%M:%S"}, {"label": "一周的第几天", "value": "%w"}, {"label": "一年的第几天", "value": "%j"}, {"label": "一年的第几周", "value": "%W"}, {"label": "XXXX年XX月XX日", "value": "%Y年%m月%d日"}, {"label": "XXXX年XX月XX日 XX:XX", "value": "%Y年%m月%d日 %H:%M"}, {"label": "XXXX年XX月XX日 XX:XX:XX", "value": "%Y年%m月%d日 %H:%M:%S"}], "default": "%Y-%m-%d %H:%M:%S", "required": true}], "outputList": [{"types": "Str", "formType": {"type": "RESULT"}, "key": "format_datetime", "title": "时间文本", "tip": ""}], "icon": "output-formatted-time", "helpManual": ""}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:17');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('286','TimeProcess.get_current_time','{"key": "TimeProcess.get_current_time", "title": "获取当前时间", "version": "1.0.2", "src": "astronverse.dataprocess.time.TimeProcess().get_current_time", "comment": "获取当前时间，格式为 @{time_format}，返回当前时间对象 @{current_time}", "inputList": [{"types": "TimeFormatType", "formType": {"type": "SELECT"}, "key": "time_format", "title": "时间格式", "name": "time_format", "tip": "", "options": [{"label": "年-月-日", "value": "%Y-%m-%d"}, {"label": "年-月-日 时:分:秒", "value": "%Y-%m-%d %H:%M:%S"}, {"label": "年-月-日 时:分", "value": "%Y-%m-%d %H:%M"}, {"label": "年/月/日", "value": "%Y/%m/%d"}, {"label": "年/月/日 时:分", "value": "%Y/%m/%d %H:%M"}, {"label": "年/月/日 时:分:秒", "value": "%Y/%m/%d %H:%M:%S"}, {"label": "年月日", "value": "%Y%m%d"}, {"label": "时:分", "value": "%H:%M"}, {"label": "时:分:秒", "value": "%H:%M:%S"}, {"label": "一周的第几天", "value": "%w"}, {"label": "一年的第几天", "value": "%j"}, {"label": "一年的第几周", "value": "%W"}, {"label": "XXXX年XX月XX日", "value": "%Y年%m月%d日"}, {"label": "XXXX年XX月XX日 XX:XX", "value": "%Y年%m月%d日 %H:%M"}, {"label": "XXXX年XX月XX日 XX:XX:XX", "value": "%Y年%m月%d日 %H:%M:%S"}], "default": "%Y-%m-%d %H:%M:%S", "required": true}], "outputList": [{"types": "Date", "formType": {"type": "RESULT"}, "key": "current_time", "title": "当前时间对象", "tip": "返回值为时间对象，可通过快捷函数或转化原子能力输出字符串形式"}], "icon": "get-current-time", "helpManual": ""}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:17');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('287','TimeProcess.get_time_difference','{"key": "TimeProcess.get_time_difference", "title": "获取时间差", "version": "1.0.2", "src": "astronverse.dataprocess.time.TimeProcess().get_time_difference", "comment": "获取 @{time_1} 和 @{time_2} 之间的时间差，单位为 @{time_unit}，返回时间差 @{time_difference}", "inputList": [{"types": "Date", "formType": {"type": "INPUT_VARIABLE_PYTHON_DATETIME"}, "key": "time_1", "title": "时间对象1", "name": "time_1", "tip": "", "required": true}, {"types": "Date", "formType": {"type": "INPUT_VARIABLE_PYTHON_DATETIME"}, "key": "time_2", "title": "时间对象2", "name": "time_2", "tip": "", "required": true}, {"types": "TimeUnitType", "formType": {"type": "SELECT"}, "key": "time_unit", "title": "时间单位", "name": "time_unit", "tip": "", "options": [{"label": "秒", "value": "second"}, {"label": "分", "value": "minute"}, {"label": "时", "value": "hour"}, {"label": "天", "value": "day"}, {"label": "月", "value": "month"}, {"label": "年", "value": "year"}], "default": "second", "required": true}], "outputList": [{"types": "Int", "formType": {"type": "RESULT"}, "key": "time_difference", "title": "时间差", "tip": ""}], "icon": "get-time-difference", "helpManual": ""}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:17');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('288','TimeProcess.set_time','{"key": "TimeProcess.set_time", "title": "设置时间", "version": "1.0.2", "src": "astronverse.dataprocess.time.TimeProcess().set_time", "comment": "设置时间 @{time}，设置方式为 @{change_type}，返回设置后的时间对象 @{set_time}", "inputList": [{"types": "Date", "formType": {"type": "INPUT_VARIABLE_PYTHON_DATETIME"}, "key": "time", "title": "时间对象", "name": "time", "tip": "", "required": true}, {"types": "TimeChangeType", "formType": {"type": "RADIO"}, "key": "change_type", "title": "日期调整方式", "name": "change_type", "tip": "", "options": [{"label": "保持不变", "value": "maintain"}, {"label": "增加时间", "value": "add"}, {"label": "减少时间", "value": "sub"}], "default": "maintain", "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "seconds", "title": "秒", "name": "seconds", "tip": "", "default": 0, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.seconds.show", "expression": "return $this.change_type.value != ''maintain''"}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "minutes", "title": "分", "name": "minutes", "tip": "", "default": 0, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.minutes.show", "expression": "return $this.change_type.value != ''maintain''"}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "hours", "title": "时", "name": "hours", "tip": "", "default": 0, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.hours.show", "expression": "return $this.change_type.value != ''maintain''"}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "days", "title": "天", "name": "days", "tip": "", "default": 0, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.days.show", "expression": "return $this.change_type.value != ''maintain'