INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('303','WinEle.similar','{"key": "WinEle.similar", "title": "获取相似元素列表（桌面）", "version": "1.0.1", "src": "astronverse.winelement.winele.WinEle().similar", "comment": "获取拾取到的元素 @{pick} 相似的元素（@{get_type}），并将相似元素数组输出至 @{get_similar_ele}，相似元素个数为@{similar_count}", "inputList": [{"types": "WinPick", "formType": {"type": "PICK", "params": {"use": "ELEMENT"}}, "key": "pick", "title": "相识元素拾取", "name": "pick", "tip": "在桌面上拾取不同位置的两个相似元素", "required": true, "noInput": true}, {"types": "WinLoopGetTypeFlag", "formType": {"type": "RADIO"}, "key": "get_type", "title": "元素操作", "name": "get_type", "tip": "选择对每个相似元素执行的操作", "options": [{"label": "获取元素对象", "value": "getElement"}, {"label": "获取元素文本内容", "value": "getText"}, {"label": "获取元素值", "value": "getValue"}, {"label": "获取元素属性", "value": "getAttribute"}], "default": "getElement", "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "attribute_name", "title": "属性名称", "name": "attribute_name", "tip": "元素操作为获取元素属性时填写，如index(位置)、Name、AutomationId、ClassName、ControlTypeName", "default": "", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.attribute_name.show", "expression": "return $this.get_type.value == ''getAttribute''"}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "wait_time", "title": "等待元素出现时间（秒）", "name": "wait_time", "tip": "超过该时间停止等待", "default": 10, "value": [{"type": "str", "value": ""}], "required": true}], "outputList": [{"types": "List", "formType": {"type": "RESULT"}, "key": "get_similar_ele", "title": "元素信息", "tip": ""}, {"types": "Int", "formType": {"type": "RESULT"}, "key": "similar_count", "title": "相似元素个数", "tip": "获取到的相似元素列表项个数"}], "icon": "get-similar-elements-win", "helpManual": "获取桌面窗口中与拾取元素相似的元素列表。支持获取元素对象（可继续点击、悬停等）、获取元素文本内容、获取元素值、获取元素属性四种操作类型"}',NULL,'2025-10-11 14:12:21','2026-02-24 17:09:17');
