rue}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "end_row", "title": "结束行号", "name": "end_row", "tip": "结束行号需要大于等于开始行号，0或者不填则读取已编辑区域", "default": 0, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.end_row.show", "expression": "return $this.copy_type.value == ''area''"}], "required": false}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "end_col", "title": "结束列号", "name": "end_col", "tip": "结束列号需要大于等于开始列号，不填则读取已编辑区域", "default": "", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.end_col.show", "expression": "return $this.copy_type.value == ''area''"}], "required": false}], "outputList": [{"types": "Str", "formType": {"type": "RESULT"}, "key": "copied_cell", "title": "复制的单元格", "tip": "以字符串形式返回复制的单元格数据", "dynamics": [{"key": "$this.copied_cell.show", "expression": "return $this.copy_type.value == ''cell''"}]}, {"types": "List", "formType": {"type": "RESULT"}, "key": "copied_row", "title": "复制的行", "tip": "以数组形式返回复制的行数据", "dynamics": [{"key": "$this.copied_row.show", "expression": "return $this.copy_type.value == ''row''"}]}, {"types": "List", "formType": {"type": "RESULT"}, "key": "copied_column", "title": "复制的列", "tip": "以数组形式返回复制的列数据", "dynamics": [{"key": "$this.copied_column.show", "expression": "return $this.copy_type.value == ''column''"}]}, {"types": "List", "formType": {"type": "RESULT"}, "key": "copied_area", "title": "复制的区域", "tip": "以二维数组形式返回复制的区域数据", "dynamics": [{"key": "$this.copied_area.show", "expression": "return $this.copy_type.value == ''area''"}]}], "icon": "copy_data_table", "helpManual": ""}',NULL,'2026-01-27 17:17:49','2026-02-24 17:09:16');
