INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('709','IeBrowserElement.input','{"key": "IeBrowserElement.input", "title": "填写输入框（ie）", "version": "1.0.5", "src": "astronverse.iebrowser.browser_element.IeBrowserElement().input", "comment": "在指定的浏览器对象 @{browser_obj} 中拾取输入框 @{element_data} ，以 @{fill_type:键盘输入/剪贴板输入} 的形式输入内容 ，将执行结果输出至 @{form_input}", "inputList": [{"types": "Browser", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "browser_obj", "title": "浏览器对象", "name": "browser_obj", "tip": "选择要等待页面所在的浏览器对象", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "WebPick", "formType": {"type": "PICK", "params": {"use": "WebPick"}}, "key": "element_data", "title": "拾取输入框", "name": "element_data", "tip": "拾取需要填写内容的输入框元素", "required": true, "noInput": true}, {"types": "Bool", "formType": {"type": "SWITCH", "params": {}}, "key": "simulate_flag", "title": "模拟人工输入", "name": "simulate_flag", "tip": "模拟人工输入是模拟人为操作方式输入，否则将根据元素的自动化接口进行输入", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": false, "required": false}, {"types": "FillInputForFillTypeFlag", "formType": {"type": "RADIO"}, "key": "fill_type", "title": "输入类型", "name": "fill_type", "tip": "选择填写输入框的方式", "options": [{"label": "键盘输入", "value": "text"}, {"label": "剪贴板", "value": "clipboard"}], "default": "text", "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "fill_input", "title": "输入内容", "name": "fill_input", "tip": "填写输入框的内容", "default": "", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.fill_input.show", "expression": "return $this.fill_type.value == ''text''"}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "element_timeout", "title": "等待元素出现时间（秒）", "name": "element_timeout", "tip": "超过该时间停止等待", "default": 10, "value": [{"type": "str", "value": ""}], "required": true}, {"types": "Float", "formTy