INPUT_VARIABLE_PYTHON"}, "key": "x_custom_scroll_dis", "title": "横向自定义滚动距离", "name": "x_custom_scroll_dis", "tip": "单位为屏幕的分辨率像素px，一般为0-9999之间的数值", "default": 0, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.x_custom_scroll_dis.show", "expression": "return $this.scroll_direction.value == ''horizontal'' && $this.x_scroll_type.value == ''defined''"}], "required": true}, {"types": "ScrollbarForYScrollTypeFlag", "formType": {"type": "RADIO"}, "key": "y_scroll_type", "title": "纵向滚动位置", "name": "y_scroll_type", "tip": "", "options": [{"label": "顶部", "value": "top"}, {"label": "底部", "value": "bottom"}, {"label": "自定义", "value": "defined"}], "default": "top", "dynamics": [{"key": "$this.y_scroll_type.show", "expression": "return $this.scroll_direction.value == ''vertical''"}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "y_custom_scroll_dis", "title": "纵向自定义滚动距离", "name": "y_custom_scroll_dis", "tip": "单位为屏幕的分辨率像素px，一般为0-9999之间的数值", "default": 0, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.y_custom_scroll_dis.show", "expression": "return $this.scroll_direction.value == ''vertical'' && $this.y_scroll_type.value == ''defined''"}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "element_timeout", "title": "等待元素出现时间（秒）", "name": "element_timeout", "tip": "超过该时间停止等待", "default": 10, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.element_timeout.show", "expression": "return $this.scrollbar_type.value == ''customEle''"}], "required": true}], "outputList": [], "icon": "mouse-scroll-webpage", "helpManual": ""}',NULL,'2026-02-06 17:44:39','2026-02-24 17:09:16');
