T_VARIABLE_PYTHON"}, "key": "timeout", "title": "加载延时时间（秒）", "name": "timeout", "tip": "", "default": 20, "value": [{"type": "str", "value": ""}], "level": "normal", "dynamics": [{"key": "$this.timeout.show", "expression": "return $this.wait_load_success.value == true"}], "required": true}, {"types": "CommonForTimeoutHandleType", "formType": {"type": "RADIO"}, "key": "timeout_handle_type", "title": "延时超时后执行", "name": "timeout_handle_type", "tip": "延时处理方式，终止即停止网页加载，跳过即跳过等待加载，不影响网页加载", "options": [{"label": "终止", "value": "execError"}, {"label": "跳过", "value": "stopLoad"}], "default": "execError", "level": "normal", "dynamics": [{"key": "$this.timeout_handle_type.show", "expression": "return $this.wait_load_success.value == true"}], "required": true}], "outputList": [{"types": "Browser", "formType": {"type": "RESULT"}, "key": "web_open", "title": "浏览器对象", "tip": "输出打开的浏览器对象,使用此网页对象可实现网页自动化"}], "icon": "open-browser", "helpManual": ""}',NULL,'2026-02-06 17:44:39','2026-02-24 17:09:16');
