INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('769','ListProcess.filter_empty_items','{"key": "ListProcess.filter_empty_items", "title": "过滤空值项", "version": "1.0.2", "src": "astronverse.dataprocess.list.ListProcessExtend().filter_empty_items", "comment": "删除列表 @{list_data} 中的空值项（一维列表删除空值项，二维列表删除全空行），返回过滤后的列表 @{filtered_list_data}", "inputList": [{"types": "Any", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "list_data", "title": "列表数据", "name": "list_data", "tip": "一维列表移除 None、空串、纯空白串；二维列表移除整行均为空值的行", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "Bool", "formType": {"type": "SWITCH", "params": {}}, "key": "only_trim_trailing", "title": "仅去除末尾空值", "name": "only_trim_trailing", "tip": "勾选后仅移除末尾连续的空值项（或空行），适合处理表格尾部空行", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": false, "required": true}], "outputList": [{"types": "List", "formType": {"type": "RESULT"}, "key": "filtered_list_data", "title": "过滤后的列表", "tip": ""}], "icon": "list-remove-multiple", "helpManual": ""}',NULL,'2026-08-15 12:00:00','2026-08-15 12:00:00');
