INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('787','ListProcess.group_2d_list','{"key": "ListProcess.group_2d_list", "title": "二维列表分组", "version": "1.0.2", "src": "astronverse.dataprocess.list.ListProcessExtend().group_2d_list", "comment": "将二维列表 @{list_data} 按第 @{column_index} 列的内容分组，结果为 @{grouped_list_data}", "inputList": [{"types": "Any", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "list_data", "title": "二维列表", "name": "list_data", "tip": "", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "Any", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "column_index", "title": "关键列索引", "name": "column_index", "tip": "从0开始，支持负数；按该列的值分组", "default": 0, "value": [{"type": "str", "value": ""}], "required": true}], "outputList": [{"types": "List", "formType": {"type": "RESULT"}, "key": "grouped_list_data", "title": "分组后的多维列表", "tip": "三维列表，每组包含该列值相同的全部行"}], "icon": "get-dict-all-keys", "helpManual": ""}',NULL,'2026-08-15 12:00:00','2026-08-15 12:00:00');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('788','ListProcess.unique_2d_list_by_column','{"key": "ListProcess.unique_2d_list_by_column", "title": "二维列表按列去重", "version": "1.0.2", "src": "astronverse.dataprocess.list.ListProcessExtend().unique_2d_list_by_column", "comment": "将二维列表 @{list_data} 按第 @{column_index} 列去重，重复行只保留第一行，结果为 @{unique_2d_list}", "inputList": [{"types": "Any", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "list_data", "title": "二维列表", "name": "list_data", "tip": "", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "Any", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "column_index", "title": "列索引", "name": "column_index", "tip": "从0开始，支持负数；该列内容相同的行视为重复行", "default": 0, "value": [{"type": "str", "value": ""}], "required": true}], "outputList": [{"types": "List", "formType": {"type": "RESULT"}, "key": "unique_2d_list", "title": "去重后的列表", "tip": ""}], "icon": "list-remove-duplicates", "helpManual": ""}',NULL,'2026-08-15 12:00:00','2026-08-15 12:00:00');
