INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('791','ListProcess.get_columns_from_2d_list','{"key": "ListProcess.get_columns_from_2d_list", "title": "获取二维列表指定列", "version": "1.0.2", "src": "astronverse.dataprocess.list.ListProcessExtend().get_columns_from_2d_list", "comment": "获取二维列表 @{list_data} 的第 @{column_indexes} 列数据，结果为 @{selected_2d_list}", "inputList": [{"types": "Any", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "list_data", "title": "二维列表", "name": "list_data", "tip": "", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "column_indexes", "title": "列序号", "name": "column_indexes", "tip": "多个列序号之间用英文逗号分隔，如 0,2；只要一列时返回一维列表", "default": "", "value": [{"type": "str", "value": ""}], "required": true}], "outputList": [{"types": "List", "formType": {"type": "RESULT"}, "key": "selected_2d_list", "title": "获取的列数据", "tip": "单列为一维列表，多列为二维列表"}], "icon": "get-list-value-by-index", "helpManual": ""}',NULL,'2026-08-15 12:00:00','2026-08-15 12:00:00');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('792','System.wait','{"key": "System.wait", "title": "\\u7b49\\u5f85", "version": "1.0.1", "src": "astronverse.system.system.System().wait", "comment": "\\u7b49\\u5f85\\u6307\\u5b9a\\u65f6\\u957f\\u540e\\u7ee7\\u7eed\\u6267\\u884c\\u6d41\\u7a0b\\uff0c\\u5b9e\\u9645\\u7b49\\u5f85\\u65f6\\u957f\\u4fdd\\u5b58\\u81f3 @{wait_seconds}", "inputList": [{"types": "WaitType", "formType": {"type": "RADIO"}, "key": "wait_type", "title": "\\u7b49\\u5f85\\u65b9\\u5f0f", "name": "wait_type", "tip": "\\u9009\\u62e9\\u56fa\\u5b9a\\u65f6\\u957f\\u6216\\u968f\\u673a\\u65f6\\u957f", "options": [{"label": "\\u56fa\\u5b9a\\u65f6\\u957f", "value": "fixed"}, {"label": "\\u968f\\u673a\\u65f6\\u957f", "value": "random"}], "default": "fixed", "required": true}, {"types": "Float", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "delay", "title": "\\u65f6\\u957f(\\u79d2)", "name": "delay", "tip": "\\u8f93\\u5165\\u7b49\\u5f85\\u65f6\\u957f\\uff0c\\u5355\\u4f4d\\u4e3a\\u79d2\\uff0c\\u652f\\u6301\\u5c0f\\u6570\\u59820.01", "default": 1, "dynamics": [{"key": "$this.delay.show", "expression": "return $this.wait_type.value == ''fixed''"}], "required": true}, {"types": "Float", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "min_delay", "title": "\\u6700\\u5c0f\\u65f6\\u957f(\\u79d2)", "name": "min_delay", "tip": "\\u968f\\u673a\\u7b49\\u5f85\\u65f6\\u957f\\u7684\\u4e0b\\u9650\\uff0c\\u5355\\u4f4d\\u4e3a\\u79d2", "default": 1, "dynamics": [{"key": "$this.min_delay.show", "expression": "return $this.wait_type.value == ''random''"}], "required": true}, {"types": "Float", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "max_delay", "title": "\\u6700\\u5927\\u65f6\\u957f(\\u79d2)", "name": "max_delay", "tip": "\\u968f\\u673a\\u7b49\\u5f85\\u65f6\\u957f\\u7684\\u4e0a\\u9650\\uff0c\\u5355\\u4f4d\\u4e3a\\u79d2", "default": 5, "dynamics": [{"key": "$this.max_delay.show", "expression": "return $this.wait_type.value == ''random''"}], "required": true}], "outputList": [{"types": "Float", "formType": {"type": "RESULT"}, "key": "wait_seconds", "title": "\\u8f93\\u51fa\\u5b9e\\u9645\\u7b49\\u5f85\\u65f6\\u957f(\\u79d2)\\u81f3\\u53d8\\u91cf", "tip": "\\u6d41\\u7a0b\\u5b9e\\u9645\\u7b49\\u5f85\\u7684\\u65f6\\u957f\\uff0c\\u968f\\u673a\\u6a21\\u5f0f\\u4e0b\\u4e3a\\u968f\\u673a\\u53d6\\u5230\\u7684\\u65f6\\u957f"}], "icon": "set-time", "helpManual": "\\u8ba9\\u6d41\\u7a0b\\u7b49\\u5f85\\u4e00\\u6bb5\\u65f6\\u95f4\\u540e\\u518d\\u7ee7\\u7eed\\u6267\\u884c\\uff0c\\u652f\\u6301\\u56fa\\u5b9a\\u65f6\\u957f\\u4e0e\\u968f\\u673a\\u65f6\\u957f\\u4e24\\u79cd\\u6a21\\u5f0f\\u3002\\u56fa\\u5b9a\\u65f6\\u957f\\u53ef\\u76f4\\u63a5\\u8f93\\u5165\\u5c0f\\u6570\\u5b9e\\u73b0\\u6beb\\u79d2\\u7ea7\\u7b49\\u5f85\\uff08\\u59820.01\\u79d2\\uff09\\uff1b\\u968f\\u673a\\u65f6\\u957f\\u5728\\u6700\\u5c0f\\u503c\\u4e0e\\u6700\\u5927\\u503c\\u4e4b\\u95f4\\u968f\\u673a\\u53d6\\u503c\\uff0c\\u9002\\u7528\\u4e8e\\u6a21\\u62df\\u4eba\\u5de5\\u64cd\\u4f5c\\u95f4\\u9694"}',NULL,'2026-08-15 12:00:00','2026-08-15 12:00:00');
