INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('811','BrowserSoftware.set_dialog_handler','{"key": "BrowserSoftware.set_dialog_handler", "title": "\\u81ea\\u52a8\\u5904\\u7406\\u7f51\\u9875\\u5f39\\u6846", "version": "1.0.5", "src": "astronverse.browser.browser_software.BrowserSoftware().set_dialog_handler", "comment": "\\u5f00\\u542f\\u540e\\u6d4f\\u89c8\\u5668\\u5bf9\\u8c61 @{browser_obj} \\u4e2d\\u7684alert/confirm/prompt\\u5f39\\u6846\\u5c06\\u81ea\\u52a8\\u70b9\\u51fb@{button}\\uff0cprompt\\u5f39\\u6846\\u81ea\\u52a8\\u8f93\\u5165 @{prompt_text}", "inputList": [{"types": "Browser", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "browser_obj", "title": "\\u6d4f\\u89c8\\u5668\\u5bf9\\u8c61", "name": "browser_obj", "tip": "\\u9009\\u62e9\\u8981\\u81ea\\u52a8\\u5904\\u7406\\u5f39\\u6846\\u7684\\u6d4f\\u89c8\\u5668\\u5bf9\\u8c61", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "Bool", "formType": {"type": "CHECKBOX"}, "key": "enable", "title": "\\u5f00\\u542f\\u81ea\\u52a8\\u5904\\u7406", "name": "enable", "tip": "\\u5f00\\u542f\\u540e\\u5f39\\u6846\\u81ea\\u52a8\\u5904\\u7406\\uff0c\\u5173\\u95ed\\u540e\\u6062\\u590d\\u9ed8\\u8ba4\\u884c\\u4e3a", "options": [{"label": "\\u662f", "value": true}, {"label": "\\u5426", "value": false}], "default": true, "dynamics": [{"key": "$this.button.show", "expression": "return $this.enable.value == true"}, {"key": "$this.prompt_text.show", "expression": "return $this.enable.value == true && $this.button.value == ''ok''"}], "required": false}, {"types": "DialogButtonTypeFlag", "formType": {"type": "RADIO"}, "key": "button", "title": "\\u81ea\\u52a8\\u70b9\\u51fb\\u6309\\u94ae", "name": "button", "tip": "\\u5f39\\u6846\\u51fa\\u73b0\\u65f6\\u81ea\\u52a8\\u70b9\\u51fb\\u786e\\u5b9a\\u6216\\u53d6\\u6d88", "options": [{"label": "\\u786e\\u5b9a", "value": "ok"}, {"label": "\\u53d6\\u6d88", "value": "cancel"}], "default": "ok", "dynamics": [{"key": "$this.button.show", "expression": "return $this.enable.value == true"}], "required": false}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "prompt_text", "title": "prompt\\u8f93\\u5165\\u5185\\u5bb9", "name": "prompt_text", "tip": "prompt\\u5f39\\u6846\\u51fa\\u73b0\\u65f6\\u81ea\\u52a8\\u8f93\\u5165\\u7684\\u6587\\u672c\\u5185\\u5bb9", "default": "", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.prompt_text.show", "expression": "return $this.enable.value == true && $this.button.value == ''ok''"}], "required": false}], "outputList": [], "icon": "message-dialog", "helpManual": "\\u5f00\\u542f\\u81ea\\u52a8\\u5904\\u7406\\u540e\\uff0c\\u7f51\\u9875\\u539f\\u751f\\u7684\\u8b66\\u544a\\u6846\\u3001\\u786e\\u8ba4\\u6846\\u3001\\u8f93\\u5165\\u6846\\u4e0d\\u518d\\u963b\\u585e\\u6d41\\u7a0b\\uff0c\\u7531\\u63d2\\u4ef6\\u81ea\\u52a8\\u4ee3\\u66ff\\u4eba\\u5de5\\u70b9\\u51fb\\u6309\\u94ae\\uff1b\\u5173\\u95ed\\u540e\\u6062\\u590d\\u6d4f\\u89c8\\u5668\\u9ed8\\u8ba4\\u884c\\u4e3a"}',NULL,'2026-08-15 12:00:00','2026-08-15 12:00:00');
