INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('813','WinEle.set_select','{"key": "WinEle.set_select", "title": "设置下拉框（桌面）", "version": "1.0.0", "src": "astronverse.winelement.winele.WinEle().set_select", "comment": "设置下拉框元素 @{pick} ，通过@{select_type}选择选项", "inputList": [{"types": "WinPick", "formType": {"type": "PICK", "params": {"use": "ELEMENT"}}, "key": "pick", "title": "元素拾取", "name": "pick", "tip": "", "required": true, "noInput": true}, {"types": "ElementSelectTypeFlag", "formType": {"type": "RADIO"}, "key": "select_type", "title": "选择方式", "name": "select_type", "tip": "按选项内容或选项位置选择", "options": [{"label": "按选项内容选择", "value": "byText"}, {"label": "按选项位置选择", "value": "byIndex"}], "default": "byText", "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "item_text", "title": "选项内容", "name": "item_text", "tip": "按选项内容选择时填写，支持模糊匹配", "default": "", "value": [{"type": "str", "value": ""}], "required": true, "dynamics": [{"key": "$this.item_text.show", "expression": "return $this.select_type.value == ''byText''"}]}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "item_index", "title": "选项位置", "name": "item_index", "tip": "按选项位置选择时填写，从1开始", "default": 1, "value": [{"type": "str", "value": ""}], "required": true, "dynamics": [{"key": "$this.item_index.show", "expression": "return $this.select_type.value == ''byIndex''"}]}, {"types": "Float", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "wait_time", "title": "等待元素出现时间（秒）", "name": "wait_time", "tip": "超过该时间停止等待", "default": 10.0, "value": [{"type": "str", "value": ""}], "required": true}], "outputList": [], "icon": "fill-input-win", "helpManual": "设置桌面应用中的下拉框/组合框控件。支持按选项内容（模糊匹配）或选项位置（从1开始）两种方式选择，自动展开和收起下拉列表"}',NULL,'2026-08-16 12:00:00','2026-08-16 12:00:00');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('814','WinEle.set_checked','{"key": "WinEle.set_checked", "title": "设置复选框（桌面）", "version": "1.0.0", "src": "astronverse.winelement.winele.WinEle().set_checked", "comment": "设置复选框元素 @{pick} ，操作方式为 @{check_type}", "inputList": [{"types": "WinPick", "formType": {"type": "PICK", "params": {"use": "ELEMENT"}}, "key": "pick", "title": "元素拾取", "name": "pick", "tip": "", "required": true, "noInput": true}, {"types": "ElementCheckedTypeFlag", "formType": {"type": "RADIO"}, "key": "check_type", "title": "操作方式", "name": "check_type", "tip": "勾选、取消勾选或反选", "options": [{"label": "勾选", "value": "check"}, {"label": "取消勾选", "value": "uncheck"}, {"label": "反选", "value": "toggle"}], "default": "check", "required": true}, {"types": "Float", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "wait_time", "title": "等待元素出现时间（秒）", "name": "wait_time", "tip": "超过该时间停止等待", "default": 10.0, "value": [{"type": "str", "value": ""}], "required": true}], "outputList": [], "icon": "click-element-win", "helpManual": "设置桌面应用中的复选框/单选框控件状态。优先使用UIA接口设置，不支持时自动回退为点击切换"}',NULL,'2026-08-16 12:00:00','2026-08-16 12:00:00');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('815','WinEle.set_value','{"key": "WinEle.set_value", "title": "设置元素值（桌面）", "version": "1.0.0", "src": "astronverse.winelement.winele.WinEle().set_value", "comment": "通过UIA接口直接设置元素 @{pick} 的值为 @{value} ，一般用于输入框和下拉框", "inputList": [{"types": "WinPick", "formType": {"type": "PICK", "params": {"use": "ELEMENT"}}, "key": "pick", "title": "元素拾取", "name": "pick", "tip": "", "required": true, "noInput": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "value", "title": "元素值", "name": "value", "tip": "设置到元素上的值", "default": "", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "Float", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "wait_time", "title": "等待元素出现时间（秒）", "name": "wait_time", "tip": "超过该时间停止等待", "default": 10.0, "value": [{"type": "str", "value": ""}], "required": true}], "outputList": [], "icon": "fill-input-win", "helpManual": "通过UIA ValuePattern接口直接设置元素值，不经过键盘输入，适用于输入框、下拉框等支持值设置的控件"}',NULL,'2026-08-16 12:00:00','2026-08-16 12:00:00');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('816','WinEle.wait_element','{"key": "WinEle.wait_element", "title": "等待元素（桌面）", "version": "1.0.0", "src": "astronverse.winelement.winele.WinEle().wait_element", "comment": "等待元素 @{pick} (@{wait_type})，最长等待 @{wait_time} 秒，结果保存至 @{wait_result}", "inputList": [{"types": "WinPick", "formType": {"type": "PICK", "params": {"use": "ELEMENT"}}, "key": "pick", "title": "元素拾取", "name": "pick", "tip": "", "required": true, "noInput": true}, {"types": "ElementWaitTypeFlag", "formType": {"type": "RADIO"}, "key": "wait_type", "title": "等待方式", "name": "wait_type", "tip": "等待元素出现或消失", "options": [{"label": "等待元素出现", "value": "appear"}, {"label": "等待元素消失", "value": "disappear"}], "default": "appear", "required": true}, {"types": "Float", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "wait_time", "title": "等待时间（秒）", "name": "wait_time", "tip": "在该时间内持续检测", "default": 10.0, "value": [{"type": "str", "value": ""}], "required": true}], "outputList": [{"types": "Bool", "formType": {"type": "RESULT"}, "key": "wait_result", "title": "等待结果", "tip": "true表示等待成功，false表示超时"}], "icon": "check-window-exists", "helpManual": "在指定时间内等待桌面元素出现或消失，常用于等待窗口内容加载完成或弹窗关闭"}',NULL,'2026-08-16 12:00:00','2026-08-16 12:00:00');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('817','WinEle.get_element_info','{"key": "WinEle.get_element_info", "title": "获取元素信息（桌面）", "version": "1.0.0", "src": "astronverse.winelement.winele.WinEle().get_element_info", "comment": "获取元素 @{pick} 的信息（@{info_type}），保存至 @{ele_info}", "inputList": [{"types": "WinPick", "formType": {"type": "PICK", "params": {"use": "ELEMENT"}}, "key": "pick", "title": "元素拾取", "name": "pick", "tip": "", "required": true, "noInput": true}, {"types": "ElementInfoTypeFlag", "formType": {"type": "RADIO"}, "key": "info_type", "title": "信息类型", "name": "info_type", "tip": "获取元素文本、值或属性", "options": [{"label": "获取元素文本内容", "value": "text"}, {"label": "获取元素值", "value": "value"}, {"label": "获取元素属性", "value": "attribute"}], "default": "text", "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "attribute_name", "title": "属性名称", "name": "attribute_name", "tip": "信息类型为获取元素属性时填写，如Name、AutomationId、ClassName、ControlTypeName", "default": "", "value": [{"type": "str", "value": ""}], "required": true, "dynamics": [{"key": "$this.attribute_name.show", "expression": "return $this.info_type.value == ''attribute''"}]}, {"types": "Float", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "wait_time", "title": "等待元素出现时间（秒）", "name": "wait_time", "tip": "超过该时间停止等待", "default": 10.0, "value": [{"type": "str", "value": ""}], "required": true}], "outputList": [{"types": "Any", "formType": {"type": "RESULT"}, "key": "ele_info", "title": "元素信息", "tip": ""}], "icon": "get-element-text-win", "helpManual": "获取桌面元素的文本内容、值或指定属性（如Name、AutomationId、ClassName、ControlTypeName等）"}',NULL,'2026-08-16 12:00:00','2026-08-16 12:00:00');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('818','WinEle.get_element_position','{"key": "WinEle.get_element_position", "title": "获取元素位置（桌面）", "version": "1.0.0", "src": "astronverse.winelement.winele.WinEle().get_element_position", "comment": "获取元素 @{pick} 相对@{relative_to}的位置信息", "inputList": [{"types": "WinPick", "formType": {"type": "PICK", "params": {"use": "ELEMENT"}}, "key": "pick", "title": "元素拾取", "name": "pick", "tip": "", "required": true, "noInput": true}, {"types": "PositionRelativeToFlag", "formType": {"type": "RADIO"}, "key": "relative_to", "title": "参照物", "name": "relative_to", "tip": "相对屏幕或元素所在窗口左上角", "options": [{"label": "相对屏幕左上角", "value": "screen"}, {"label": "相对元素所在窗口左上角", "value": "window"}], "default": "screen", "required": true}, {"types": "Float", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "wait_time", "title": "等待元素出现时间（秒）", "name": "wait_time", "tip": "超过该时间停止等待", "default": 10.0, "value": [{"type": "str", "value": ""}], "required": true}], "outputList": [{"types": "Int", "formType": {"type": "RESULT"}, "key": "pos_left", "title": "左边距", "tip": "元素左上角横坐标"}, {"types": "Int", "formType": {"type": "RESULT"}, "key": "pos_top", "title": "上边距", "tip": "元素左上角纵坐标"}, {"types": "Int", "formType": {"type": "RESULT"}, "key": "pos_width", "title": "宽度", "tip": "元素宽度（像素）"}, {"types": "Int", "formType": {"type": "RESULT"}, "key": "pos_height", "title": "高度", "tip": "元素高度（像素）"}, {"types": "Int", "formType": {"type": "RESULT"}, "key": "center_x", "title": "中心点横坐标", "tip": "元素中心点横坐标"}, {"types": "Int", "formType": {"type": "RESULT"}, "key": "center_y", "title": "中心点纵坐标", "tip": "元素中心点纵坐标"}], "icon": "get-element-text-win", "helpManual": "获取桌面元素的位置和尺寸信息，可相对屏幕左上角或元素所在窗口左上角计算，输出左边距、上边距、宽、高及中心点坐标"}',NULL,'2026-08-16 12:00:00','2026-08-16 12:00:00');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('819','WinEle.get_relative_element','{"key": "WinEle.get_relative_element", "title": "获取关联元素（桌面）", "version": "1.0.0", "src": "astronverse.winelement.winele.WinEle().get_relative_element", "comment": "获取元素 @{pick} 的@{relative_type}，保存至 @{relative_ele}", "inputList": [{"types": "WinPick", "formType": {"type": "PICK", "params": {"use": "ELEMENT"}}, "key": "pick", "title": "元素拾取", "name": "pick", "tip": "", "required": true, "noInput": true}, {"types": "RelativeTypeFlag", "formType": {"type": "RADIO"}, "key": "relative_type", "title": "关联方式", "name": "relative_type", "tip": "父元素、子元素或同级元素", "options": [{"label": "父元素", "value": "parent"}, {"label": "第一个子元素", "value": "firstChild"}, {"label": "下一个同级元素", "value": "nextSibling"}, {"label": "上一个同级元素", "value": "prevSibling"}], "default": "parent", "required": true}, {"types": "Float", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "wait_time", "title": "等待元素出现时间（秒）", "name": "wait_time", "tip": "超过该时间停止等待", "default": 10.0, "value": [{"type": "str", "value": ""}], "required": true}], "outputList": [{"types": "WinPick", "formType": {"type": "RESULT"}, "key": "relative_ele", "title": "关联元素", "tip": "获取到的元素对象，可供其他桌面元素指令使用"}], "icon": "get-similar-elements-win", "helpManual": "获取拾取元素的关联元素：父元素、第一个子元素、上一个/下一个同级元素，输出的元素对象可直接用于其他桌面元素指令"}',NULL,'2026-08-16 12:00:00','2026-08-16 12:00:00');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('820','WinEle.drag_element','{"key": "WinEle.drag_element", "title": "拖拽元素（桌面）", "version": "1.0.0", "src": "astronverse.winelement.winele.WinEle().drag_element", "comment": "将元素 @{pick} 拖拽至@{drag_type}", "inputList": [{"types": "WinPick", "formType": {"type": "PICK", "params": {"use": "ELEMENT"}}, "key": "pick", "title": "起始元素拾取", "name": "pick", "tip": "拾取需要拖拽的元素", "required": true, "noInput": true}, {"types": "DragTypeFlag", "formType": {"type": "RADIO"}, "key": "drag_type", "title": "拖拽方式", "name": "drag_type", "tip": "拖拽至目标元素或目标点偏移量", "options": [{"label": "拖拽至目标元素上", "value": "toElement"}, {"label": "拖拽至目标点（偏移量）", "value": "toOffset"}], "default": "toElement", "required": true}, {"types": "WinPick", "formType": {"type": "PICK", "params": {"use": "ELEMENT"}}, "key": "pick_to", "title": "目标元素拾取", "name": "pick_to", "tip": "拖拽方式为目标元素时拾取拖拽目标", "required": true, "noInput": true, "dynamics": [{"key": "$this.pick_to.show", "expression": "return $this.drag_type.value == ''toElement''"}]}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "offset_x", "title": "横向偏移量", "name": "offset_x", "tip": "拖拽方式为目标点时填写，相对元素中心点的横向偏移", "default": 0, "value": [{"type": "str", "value": ""}], "required": true, "dynamics": [{"key": "$this.offset_x.show", "expression": "return $this.drag_type.value == ''toOffset''"}]}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "offset_y", "title": "纵向偏移量", "name": "offset_y", "tip": "拖拽方式为目标点时填写，相对元素中心点的纵向偏移", "default": 0, "value": [{"type": "str", "value": ""}], "required": true, "dynamics": [{"key": "$this.offset_y.show", "expression": "return $this.drag_type.value == ''toOffset''"}]}, {"types": "Float", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "wait_time", "title": "等待元素出现时间（秒）", "name": "wait_time", "tip": "超过该时间停止等待", "default": 10.0, "value": [{"type": "str", "value": ""}], "required": true}], "outputList": [], "icon": "click-element-win", "helpManual": "将桌面元素拖拽至目标元素上或按偏移量拖拽至目标点，模拟真实鼠标按下-移动-释放操作"}',NULL,'2026-08-16 12:00:00','2026-08-16 12:00:00');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('821','Window.get','{"key": "Window.get", "title": "获取窗口对象", "version": "1.0.0", "src": "astronverse.window.window.Window().get", "comment": "获取窗口对象并保存至变量 @{window_obj} ，供后续窗口指令直接调用", "inputList": [{"types": "WinPick", "formType": {"type": "PICK", "params": {"use": "WINDOW"}}, "key": "pick", "title": "窗口拾取", "name": "pick", "tip": "拾取需要获取的桌面软件窗口", "required": true, "noInput": true}, {"types": "Float", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "wait_time", "title": "等待窗口出现时间（秒）", "name": "wait_time", "tip": "超过该时间停止等待", "default": 10.0, "value": [{"type": "str", "value": ""}], "required": true}], "outputList": [{"types": "WinPick", "formType": {"type": "RESULT"}, "key": "window_obj", "title": "窗口对象", "tip": "获取到的窗口对象变量，可供其他窗口指令使用"}], "icon": "pin-window", "helpManual": "获取桌面窗口对象并保存为变量，后续窗口指令（关闭、置顶、调整大小等）可直接使用该变量，无需重复拾取"}',NULL,'2026-08-16 12:00:00','2026-08-16 12:00:00');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('822','Window.get_info','{"key": "Window.get_info", "title": "获取窗口信息", "version": "1.0.0", "src": "astronverse.window.window.Window().get_info", "comment": "获取窗口(@{pick})的信息（@{info_type}），保存至 @{window_info}", "inputList": [{"types": "WinPick", "formType": {"type": "PICK", "params": {"use": "WINDOW"}}, "key": "pick", "title": "窗口拾取", "name": "pick", "tip": "拾取需要获取信息的桌面软件窗口", "required": true, "noInput": true}, {"types": "WindowInfoTypeFlag", "formType": {"type": "RADIO"}, "key": "info_type", "title": "信息类型", "name": "info_type", "tip": "获取窗口标题、类名、进程名或位置尺寸", "options": [{"label": "窗口标题", "value": "title"}, {"label": "窗口类名", "value": "className"}, {"label": "进程名", "value": "processName"}, {"label": "窗口位置尺寸", "value": "rect"}], "default": "title", "required": true}], "outputList": [{"types": "Any", "formType": {"type": "RESULT"}, "key": "window_info", "title": "窗口信息", "tip": ""}], "icon": "resize-window", "helpManual": "获取桌面窗口的标题、类名、进程名或位置尺寸[left, top, right, bottom]，常用于窗口判断和流程分支"}',NULL,'2026-08-16 12:00:00','2026-08-16 12:00:00');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('823','Window.get_list','{"key": "Window.get_list", "title": "获取窗口列表", "version": "1.0.0", "src": "astronverse.window.window.Window().get_list", "comment": "获取所有标题包含@{title_contains}的窗口对象，输出至 @{window_obj_list} ，窗口数量为 @{window_count}", "inputList": [{"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "title_contains", "title": "标题包含", "name": "title_contains", "tip": "匹配窗口标题包含的文字，留空获取所有可见窗口", "default": "", "value": [{"type": "str", "value": ""}], "required": true}], "outputList": [{"types": "List", "formType": {"type": "RESULT"}, "key": "window_obj_list", "title": "窗口对象列表", "tip": "获取到的窗口对象数组，可供其他窗口指令使用"}, {"types": "Int", "formType": {"type": "RESULT"}, "key": "window_count", "title": "窗口数量", "tip": "获取到的窗口个数"}], "icon": "pin-window", "helpManual": "按标题关键字枚举当前系统中的可见窗口，返回窗口对象列表和数量，可配合循环指令批量操作多个窗口"}',NULL,'2026-08-16 12:00:00','2026-08-16 12:00:00');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('824','Window.move','{"key": "Window.move", "title": "移动窗口", "version": "1.0.0", "src": "astronverse.window.window.Window().move", "comment": "移动窗口(@{pick})至屏幕坐标(@{x}, @{y})", "inputList": [{"types": "WinPick", "formType": {"type": "PICK", "params": {"use": "WINDOW"}}, "key": "pick", "title": "窗口拾取", "name": "pick", "tip": "拾取需要移动的桌面软件窗口", "required": true, "noInput": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "x", "title": "横坐标x", "name": "x", "tip": "窗口移动后的左上角横坐标，单位为像素", "default": 0, "value": [{"type": "str", "value": ""}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "y", "title": "纵坐标y", "name": "y", "tip": "窗口移动后的左上角纵坐标，单位为像素", "default": 0, "value": [{"type": "str", "value": ""}], "required": true}], "outputList": [], "icon": "resize-window", "helpManual": "将桌面窗口移动至屏幕指定位置（左上角坐标），常用于窗口布局整理、多窗口协作操作"}',NULL,'2026-08-16 12:00:00','2026-08-16 12:00:00');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('825','Window.set_visible','{"key": "Window.set_visible", "title": "设置窗口显示/隐藏", "version": "1.0.0", "src": "astronverse.window.window.Window().set_visible", "comment": "设置窗口(@{pick})@{visible_type}", "inputList": [{"types": "WinPick", "formType": {"type": "PICK", "params": {"use": "WINDOW"}}, "key": "pick", "title": "窗口拾取", "name": "pick", "tip": "拾取需要设置的桌面软件窗口", "required": true, "noInput": true}, {"types": "WindowVisibleTypeFlag", "formType": {"type": "RADIO"}, "key": "visible_type", "title": "设置方式", "name": "visible_type", "tip": "显示或隐藏窗口", "options": [{"label": "显示窗口", "value": "show"}, {"label": "隐藏窗口", "value": "hide"}], "default": "show", "required": true}], "outputList": [], "icon": "pin-window", "helpManual": "设置桌面窗口显示或隐藏。隐藏窗口不关闭进程，后台运行时避免窗口干扰；显示窗口恢复其可见性"}',NULL,'2026-08-16 12:00:00','2026-08-16 12:00:00');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('826','Window.get_selected_text','{"key": "Window.get_selected_text", "title": "获取选中文字", "version": "1.0.0", "src": "astronverse.window.window.Window().get_selected_text", "comment": "获取当前激活窗口中被选中的文本，保存至 @{selected_text}", "inputList": [{"types": "Float", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "wait_time", "title": "等待时间（秒）", "name": "wait_time", "tip": "在该时间内持续检测选中文本", "default": 1.0, "value": [{"type": "str", "value": ""}], "required": true}], "outputList": [{"types": "Str", "formType": {"type": "RESULT"}, "key": "selected_text", "title": "选中文本", "tip": "获取到的被选中文本内容"}], "icon": "resize-window", "helpManual": "获取当前激活窗口（或桌面）中被鼠标或键盘选中的文本内容，通过系统UIA文本模式读取"}',NULL,'2026-08-16 12:00:00','2026-08-16 12:00:00');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('827','CV.ocr_click','{"key": "CV.ocr_click", "title": "点击文本(OCR)", "version": "1.0.1", "src": "astronverse.vision.cv.CV().ocr_click", "comment": "OCR识别屏幕文本并点击文本 @{text} (@{btn_type:左键/右键}) (@{btn_model:单击/双击})位置(@{click_position})", "inputList": [{"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "text", "title": "文本内容", "name": "text", "tip": "输入待查找的文本内容，支持变量", "required": true}, {"types": "Bool", "formType": {"type": "CHECKBOX"}, "key": "is_regex", "title": "正则匹配", "name": "is_regex", "tip": "勾选后按正则表达式匹配文本", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": false, "required": false}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "x1", "title": "查找区域左上角X", "name": "x1", "tip": "0表示整个屏幕", "default": 0, "value": [{"type": "str", "value": ""}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "y1", "title": "查找区域左上角Y", "name": "y1", "tip": "0表示整个屏幕", "default": 0, "value": [{"type": "str", "value": ""}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "x2", "title": "查找区域右下角X", "name": "x2", "tip": "0表示整个屏幕", "default": 0, "value": [{"type": "str", "value": ""}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "y2", "title": "查找区域右下角Y", "name": "y2", "tip": "0表示整个屏幕", "default": 0, "value": [{"type": "str", "value": ""}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "similar_index", "title": "相似结果位置", "name": "similar_index", "tip": "匹配到多个结果时点击第几个，从1开始，默认第1个", "default": 1, "value": [{"type": "str", "value": ""}], "required": false}, {"types": "BtnType", "formType": {"type": "RADIO"}, "key": "btn_type", "title": "鼠标按键", "name": "btn_type", "tip": "选择点击鼠标上的键位", "options": [{"label": "左键", "value": "left"}, {"label": "中键", "value": "middle"}, {"label": "右键", "value": "right"}], "default": "left", "required": false}, {"types": "BtnModel", "formType": {"type": "RADIO"}, "key": "btn_model", "title": "点击方式", "name": "btn_model", "tip": "选择单击或双击", "options": [{"label": "单击", "value": "click"}, {"label": "双击", "value": "double_click"}], "default": "click", "required": false}, {"types": "ControlType", "formType": {"type": "SELECT"}, "key": "ctrl_type", "title": "键盘辅助按键", "name": "ctrl_type", "tip": "选择键盘辅助按键，默认为无", "options": [{"label": "无", "value": "none"}, {"label": "Ctrl键", "value": "ctrl"}, {"label": "Alt键", "value": "alt"}, {"label": "Shift键", "value": "shift"}, {"label": "Win键", "value": "win"}, {"label": "space", "value": "space"}], "default": "none", "level": "advanced", "required": false}, {"types": "PositionType", "formType": {"type": "RADIO"}, "key": "click_position", "title": "点击位置", "name": "click_position", "tip": "点击匹配文本的中心点、随机位置或指定位置", "options": [{"label": "中心点", "value": "center"}, {"label": "随机位置", "value": "random"}, {"label": "指定位置", "value": "specific"}], "default": "center", "required": false}, {"types": "Any", "formType": {"type": "GRID"}, "key": "specified_position", "title": "指定位置", "name": "specified_position", "tip": "点击位置为指定位置时选择九宫格位置", "default": 5, "dynamics": [{"key": "$this.specified_position.show", "expression": "return $this.click_position.value == ''specific''"}], "required": false}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "horizontal_move", "title": "横向平移", "name": "horizontal_move", "tip": "点击位置为指定位置时填写，点击位置横向偏移量", "default": 0, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.horizontal_move.show", "expression": "return $this.click_position.value == ''specific''"}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "vertical_move", "title": "纵向平移", "name": "vertical_move", "tip": "点击位置为指定位置时填写，点击位置纵向偏移量", "default": 0, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.vertical_move.show", "expression": "return $this.click_position.value == ''specific''"}], "required": true}, {"types": "MoveType", "formType": {"type": "RADIO"}, "key": "move_type", "title": "移动方式", "name": "move_type", "tip": "", "options": [{"label": "匀速直线", "value": "linear"}, {"label": "模拟人工", "value": "simulation"}, {"label": "瞬时移动", "value": "teleportation"}], "default": "linear", "level": "advanced", "required": false}, {"types": "Speed", "formType": {"type": "RADIO"}, "key": "move_speed", "title": "移动速度", "name": "move_speed", "tip": "", "options": [{"label": "慢速", "value": "slow"}, {"label": "正常", "value": "normal"}, {"label": "快速", "value": "fast"}], "default": "normal", "level": "advanced", "dynamics": [{"key": "$this.move_speed.show", "expression": "return [''linear'',''simulation''].includes($this.move_type.value)"}], "required": false}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "wait_time", "title": "超时时间(秒)", "name": "wait_time", "tip": "在该时间内持续检测，默认10秒", "default": 10, "value": [{"type": "str", "value": ""}], "level": "advanced", "required": false}], "outputList": [], "icon": "general-text-recognition", "helpManual": "通过OCR识别屏幕文本并点击匹配文本的位置，支持普通文本与正则表达式匹配。适用于无元素拾取能力的场景（远程桌面、画布类应用、图片化界面）。支持指定查找区域缩小识别范围提高准确率，多个匹配结果时可选择点击第几个"}',NULL,'2026-08-16 16:30:00','2026-08-16 16:30:00');
