INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('835','DataTable.sort_data_table','{"key": "DataTable.sort_data_table", "title": "数据表格排序", "version": "1.0.3", "src": "astronverse.datatable.datatable.DataTable().sort_data_table", "comment": "按列 @{sort_cols} 以 @{sort_orders} 方式排序数据表格，@{has_header:含}表头行", "inputList": [{"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "sort_cols", "title": "排序列", "name": "sort_cols", "tip": "排序依据列，多列用逗号分隔（如A,C）", "default": "A", "value": [{"type": "str", "value": ""}], "required": false}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "sort_orders", "title": "排序方式", "name": "sort_orders", "tip": "排序方式（升序/降序），多列用逗号分隔与排序列一一对应", "default": "ascending", "value": [{"type": "str", "value": ""}], "required": false}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "start_row", "title": "起始行号", "name": "start_row", "tip": "指定排序区域的起始行号（例如1，2，3...）", "default": 1, "value": [{"type": "str", "value": ""}], "required": false}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "end_row", "title": "结束行号", "name": "end_row", "tip": "结束行号需要大于等于起始行号，0或者不填则到已用最大行", "default": 0, "value": [{"type": "str", "value": ""}], "required": false}, {"types": "Bool", "formType": {"type": "SWITCH", "params": {}}, "key": "has_header", "title": "首行为表头", "name": "has_header", "tip": "勾选后首行不参与排序", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": false, "required": false}], "outputList": [], "icon": "filter_data_table", "helpManual": ""}',NULL,'2026-08-16 10:03:18','2026-08-16 10:03:18');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('836','DataTable.add_data_validation','{"key": "DataTable.add_data_validation", "title": "数据表格添加数据验证", "version": "1.0.3", "src": "astronverse.datatable.datatable.DataTable().add_data_validation", "comment": "在区域 @{validate_range} 添加 @{validate_type} 类型数据验证", "inputList": [{"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "validate_range", "title": "验证区域", "name": "validate_range", "tip": "要添加数据验证的区域（如A1:B10或A1）", "default": "A1:B10", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "ValidateType", "formType": {"type": "SELECT"}, "key": "validate_type", "title": "验证类型", "name": "validate_type", "tip": "选择数据验证类型（整数、小数、列表、日期、时间、文本长度、自定义公式）", "options": [{"label": "整数", "value": "whole"}, {"label": "小数", "value": "decimal"}, {"label": "列表", "value": "list"}, {"label": "日期", "value": "date"}, {"label": "时间", "value": "time"}, {"label": "文本长度", "value": "textLength"}, {"label": "自定义公式", "value": "custom"}], "default": "whole", "required": true}, {"types": "ValidateOperator", "formType": {"type": "SELECT"}, "key": "validate_operator", "title": "验证操作符", "name": "validate_operator", "tip": "选择验证操作符（介于、不介于、等于、不等于、大于、小于、大于等于、小于等于），列表和自定义公式类型不需要", "options": [{"label": "介于", "value": "between"}, {"label": "不介于", "value": "notBetween"}, {"label": "等于", "value": "equal"}, {"label": "不等于", "value": "notEqual"}, {"label": "大于", "value": "greaterThan"}, {"label": "小于", "value": "lessThan"}, {"label": "大于等于", "value": "greaterThanOrEqual"}, {"label": "小于等于", "value": "lessThanOrEqual"}], "default": "between", "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "formula1", "title": "条件1", "name": "formula1", "tip": "验证条件1（如介于的最小值，或列表的取值），列表类型多个值用逗号分隔", "default": "", "value": [{"type": "str", "value": ""}], "required": false}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "formula2", "title": "条件2", "name": "formula2", "tip": "验证条件2（如介于的最大值）", "default": "", "value": [{"type": "str", "value": ""}], "required": false}, {"types": "Bool", "formType": {"type": "SWITCH", "params": {}}, "key": "allow_blank", "title": "允许空值", "name": "allow_blank", "tip": "勾选后允许输入空值", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": true, "required": false}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "error_msg", "title": "错误提示", "name": "error_msg", "tip": "输入无效时的提示信息", "default": "", "value": [{"type": "str", "value": ""}], "required": false}], "outputList": [], "icon": "write_data_table", "helpManual": ""}',NULL,'2026-08-16 10:03:18','2026-08-16 10:03:18');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('837','DataTable.set_format','{"key": "DataTable.set_format", "title": "设置数据表格格式", "version": "1.0.3", "src": "astronverse.datatable.datatable.DataTable().set_format", "comment": "设置数据表格 @{format_type} 的格式（字体、填充、对齐、边框），字体 @{font_name} 字号 @{font_size} 是否加粗 @{bold}", "inputList": [{"types": "BaseOperateType", "formType": {"type": "SELECT"}, "key": "format_type", "title": "格式设置方式", "name": "format_type", "tip": "选择格式设置的方式（单元格、行、列、区域）", "options": [{"label": "单元格", "value": "cell"}, {"label": "行", "value": "row"}, {"label": "列", "value": "column"}, {"label": "区域", "value": "area"}], "default": "area", "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "row", "title": "行号", "name": "row", "tip": "指定要设置的行号（例如1，2，3...），单元格/行方式时使用", "default": 1, "value": [{"type": "str", "value": ""}], "required": false}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "col", "title": "列号", "name": "col", "tip": "指定要设置的列号（例如A，B，C，AB...），单元格/列方式时使用", "default": "A", "value": [{"type": "str", "value": ""}], "required": false}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "start_row", "title": "开始行号", "name": "start_row", "tip": "指定要设置的开始行号（例如1，2，3...），区域方式时使用", "default": 1, "value": [{"type": "str", "value": ""}], "required": false}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "start_col", "title": "开始列号", "name": "start_col", "tip": "指定要设置的开始列号（例如A，B，C，AB...），区域方式时使用", "default": "A", "value": [{"type": "str", "value": ""}], "required": false}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "end_row", "title": "结束行号", "name": "end_row", "tip": "结束行号需要大于等于开始行号，0或者不填则到已用最大行", "default": 0, "value": [{"type": "str", "value": ""}], "required": false}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "end_col", "title": "结束列号", "name": "end_col", "tip": "结束列号需要大于等于开始列号，不填则到已用最大列", "default": "", "value": [{"type": "str", "value": ""}], "required": false}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "font_name", "title": "字体名称", "name": "font_name", "tip": "字体名称（如宋体、微软雅黑），不填则不设置", "default": "", "value": [{"type": "str", "value": ""}], "required": false}, {"types": "Float", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "font_size", "title": "字号", "name": "font_size", "tip": "字体大小，0或者不填则不设置", "default": 0, "value": [{"type": "str", "value": ""}], "required": false}, {"types": "Bool", "formType": {"type": "SWITCH", "params": {}}, "key": "bold", "title": "是否加粗", "name": "bold", "tip": "勾选后设置加粗", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": false, "required": false}, {"types": "Bool", "formType": {"type": "SWITCH", "params": {}}, "key": "italic", "title": "是否斜体", "name": "italic", "tip": "勾选后设置斜体", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": false, "required": false}, {"types": "UnderlineType", "formType": {"type": "SELECT"}, "key": "underline", "title": "下划线类型", "name": "underline", "tip": "选择下划线类型（无、单下划线、双下划线）", "options": [{"label": "无下划线", "value": "none"}, {"label": "单下划线", "value": "single"}, {"label": "双下划线", "value": "double"}], "default": "none", "required": false}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "font_color", "title": "字体颜色", "name": "font_color", "tip": "字体颜色RGB值（如FF0000），不填则不设置", "default": "", "value": [{"type": "str", "value": ""}], "required": false}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "bg_color", "title": "背景颜色", "name": "bg_color", "tip": "背景颜色RGB值（如FFFF00），不填则不设置", "default": "", "value": [{"type": "str", "value": ""}], "required": false}, {"types": "HAlignType", "formType": {"type": "SELECT"}, "key": "h_align", "title": "水平对齐", "name": "h_align", "tip": "选择水平对齐方式（左对齐、居中、右对齐），不选则不设置", "options": [{"label": "不设置", "value": "none"}, {"label": "左对齐", "value": "left"}, {"label": "居中", "value": "center"}, {"label": "右对齐", "value": "right"}], "default": "none", "required": false}, {"types": "VAlignType", "formType": {"type": "SELECT"}, "key": "v_align", "title": "垂直对齐", "name": "v_align", "tip": "选择垂直对齐方式（顶部对齐、垂直居中、底部对齐），不选则不设置", "options": [{"label": "不设置", "value": "none"}, {"label": "顶部对齐", "value": "top"}, {"label": "垂直居中", "value": "center"}, {"label": "底部对齐", "value": "bottom"}], "default": "none", "required": false}, {"types": "Bool", "formType": {"type": "SWITCH", "params": {}}, "key": "wrap_text", "title": "自动换行", "name": "wrap_text", "tip": "勾选后设置自动换行", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": false, "required": false}, {"types": "BorderStyleType", "formType": {"type": "SELECT"}, "key": "border_style", "title": "边框样式", "name": "border_style", "tip": "选择边框样式（无边框、细边框、中边框、虚线、点线、双线），选择无边框则不设置", "options": [{"label": "无边框", "value": "none"}, {"label": "细边框", "value": "thin"}, {"label": "中边框", "value": "medium"}, {"label": "虚线边框", "value": "dashed"}, {"label": "点线边框", "value": "dotted"}, {"label": "双线边框", "value": "double"}], "default": "none", "required": false}], "outputList": [], "icon": "write_data_table", "helpManual": ""}',NULL,'2026-08-16 10:03:18','2026-08-16 10:03:18');
