INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('879','BrowserSoftware.http_request','{"key": "BrowserSoftware.http_request", "title": "通过网页发送HTTP请求", "version": "1.0.5", "src": "astronverse.browser.browser_software.BrowserSoftware().http_request", "comment": "在浏览器对象 @{browser_obj} 中向URL(@{url})发送(@{request_type})请求，输出至 @{response_data}", "inputList": [{"types": "Browser", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "browser_obj", "title": "浏览器对象", "name": "browser_obj", "tip": "选择已打开并完成登录的浏览器对象", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "URL", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "url", "title": "URL", "name": "url", "tip": "请求地址，建议与网页同域以携带登录Cookie", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "WebRequestTypeFlag", "formType": {"type": "SELECT"}, "key": "request_type", "title": "请求类型", "name": "request_type", "tip": "GET/POST/PUT/PATCH/DELETE/HEAD", "options": [{"label": "GET", "value": "get"}, {"label": "POST", "value": "post"}, {"label": "PUT", "value": "put"}, {"label": "PATCH", "value": "patch"}, {"label": "DELETE", "value": "delete"}, {"label": "HEAD", "value": "head"}], "default": "get", "required": false}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "headers", "title": "请求头", "name": "headers", "tip": "JSON格式的请求头字符串", "default": "", "value": [{"type": "str", "value": ""}], "required": false}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "body", "title": "请求体", "name": "body", "tip": "POST/PUT/PATCH/DELETE时的请求体内容", "default": "", "value": [{"type": "str", "value": ""}], "required": false}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "time_out", "title": "超时时间", "name": "time_out", "tip": "请求超时时间（秒）", "default": 60, "value": [{"type": "str", "value": ""}], "required": false}], "outputList": [{"types": "Dict", "formType": {"type": "RESULT"}, "key": "response_data", "title": "响应结果保存至", "tip": "包含status(状态码)、headers(响应头)、body(响应体)的字典"}], "icon": "http-request", "helpManual": "借助指定网页的登录态(Cookie)发送HTTP请求，适用于需要网页登录认证的接口；请求在网页上下文中执行，自动携带该站点的登录Cookie"}',NULL,'2026-08-16 12:43:56','2026-08-16 12:43:56');
