INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('888','Phone.click_screen','{"key": "Phone.click_screen", "title": "点击屏幕(手机)", "version": "1.0.0", "src": "astronverse.phone.phone.Phone().click_screen", "comment": "点击屏幕坐标(@{x},@{y})或图像匹配位置", "inputList": [{"types": "PhoneObject", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "conn", "title": "手机连接对象", "name": "conn", "tip": "选择通过【连接手机】创建的连接对象", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "PositionType", "formType": {"type": "RADIO"}, "key": "position_type", "title": "点击位置", "name": "position_type", "tip": "通过坐标指定/通过图像匹配", "options": [{"label": "通过坐标指定", "value": "coord"}, {"label": "通过图像匹配", "value": "image"}], "default": "coord", "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "x", "title": "横坐标", "name": "x", "tip": "相对手机屏幕左上角的横向坐标", "default": 0, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.x.show", "expression": "return $this.position_type.value == ''coord''"}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "y", "title": "纵坐标", "name": "y", "tip": "相对手机屏幕左上角的纵向坐标", "default": 0, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.y.show", "expression": "return $this.position_type.value == ''coord''"}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON_FILE", "params": {"filters": [], "file_type": "file"}}, "key": "img_path", "title": "目标图像", "name": "img_path", "tip": "图像匹配模式下选择图像文件, 点击第一个匹配位置", "default": "", "dynamics": [{"key": "$this.img_path.show", "expression": "return $this.position_type.value == ''image''"}], "required": true}, {"types": "ClickType", "formType": {"type": "RADIO"}, "key": "click_type", "title": "点击方式", "name": "click_type", "tip": "单击/双击/长按", "options": [{"label": "单击", "value": "single"}, {"label": "双击", "value": "double"}, {"label": "长按", "va