INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('889','Phone.connect','{"key": "Phone.connect", "title": "连接手机", "version": "1.0.0", "src": "astronverse.phone.phone.Phone().connect", "comment": "连接手机(@{serial})，连接对象保存至(@{conn})", "inputList": [{"types": "Any", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "target_type", "title": "连接对象", "name": "target_type", "tip": "指定手机/运行时自动选择/所有已连接的手机", "default": "auto", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "serial", "title": "手机serial", "name": "serial", "tip": "指定手机时填写, 可通过【获取手机设备列表】查看", "default": "", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.serial.show", "expression": "return $this.target_type.value == ''specified''"}], "required": true}, {"types": "Bool", "formType": {"type": "SWITCH", "params": {}}, "key": "ignore_failed", "title": "忽略连接失败的手机", "name": "ignore_failed", "tip": "连接所有手机时生效, 勾选则跳过连接失败的手机", "options": [{"label": "是", "value": true}, {"label": "否", "value": false}], "default": true, "dynamics": [{"key": "$this.ignore_failed.show", "expression": "return $this.target_type.value == ''all''"}], "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "custom_name", "title": "自定义手机名称", "name": "custom_name", "tip": "自定义手机连接名称, 保存在连接详情custom_name字段", "default": "", "required": true}, {"types": "ConnectMode", "formType": {"type": "RADIO"}, "key": "connect_mode", "title": "连接模式", "name": "connect_mode", "tip": "Uiautomator2直连(默认,数据精准)/Appium(兼容安卓9+剪贴板,需Appium服务)", "options": [{"label": "Uiautomator2模式", "value": "uiautomator2"}, {"label": "Appium模式", "value": "appium"}], "default": "uiautomator2", "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "appium_server", "title": "Appium服务地址", "name": "appium_server", "tip": "Appium模式时填写, 如http://127.0.0.1:4723", "default": "http://127.0.0.1:4723", "dynamics": [{"key": "$this.appium_server.show", "expression": "return $this.connect_mode.value == ''appium''"}], "required": true}, {"types": "UnlockType", "formType": {"type": "RADIO"}, "key": "unlock_type", "title": "连接时自动解锁", "name": "unlock_type", "tip": "选择解锁方式(无/数字密码/图案密码)", "options": [{"label": "无", "value": "none"}, {"label": "数字密码", "value": "password"}, {"label": "图案密码", "value": "pattern"}], "default": "none", "required": true}, {"types": "Str", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "unlock_secret", "title": "手机密码", "name": "unlock_secret", "tip": "数字密码或图案数字串(如5416)", "default": "", "dynamics": [{"key": "$this.unlock_secret.show", "expression": "return $this.unlock_type.value != ''none''"}], "required": true}], "outputList": [{"types": "PhoneObject", "formType": {"type": "RESULT"}, "key": "conn", "title": "保存连接对象至", "tip": "指定/自动选择模式保存手机连接对象"}, {"types": "List", "formType": {"type": "RESULT"}, "key": "conn_list", "title": "保存连接对象列表至", "tip": "所有手机模式保存连接对象列表"}, {"types": "List", "formType": {"type": "RESULT"}, "key": "failed_list", "title": "保存连接失败列表至", "tip": "勾选忽略失败手机时, 保存连接失败的serial列表"}], "icon": "phone-connect", "helpManual": "与指定/自动选择/所有已连接的手机建立连接; 指定手机需填写serial(可通过【获取手机设备列表】查看); 连接所有手机时返回(连接列表, 失败列表); 连接模式: Uiautomator2直连(默认, 数据更精准)/Appium(需先启动Appium服务, 兼容安卓9+读写剪贴板); 高级选项支持连接时自动解锁(数字密码/图案密码)"}',NULL,'2026-08-16 13:54:07','2026-08-16 14:28:18');
