INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('909','Phone.swipe_screen','{"key": "Phone.swipe_screen", "title": "滑动手机屏幕", "version": "1.0.0", "src": "astronverse.phone.phone.Phone().swipe_screen", "comment": "滑动手机屏幕(方向/坐标)", "inputList": [{"types": "PhoneObject", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "conn", "title": "手机连接对象", "name": "conn", "tip": "选择通过【连接手机】创建的连接对象", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "SwipeMode", "formType": {"type": "RADIO"}, "key": "mode", "title": "滑动方式", "name": "mode", "tip": "方向/坐标", "options": [{"label": "方向", "value": "direction"}, {"label": "坐标", "value": "coord"}], "default": "direction", "required": true}, {"types": "SwipeDirection", "formType": {"type": "SELECT"}, "key": "direction", "title": "滑动方向", "name": "direction", "tip": "向上/向下/向左/向右", "options": [{"label": "向上滑动", "value": "up"}, {"label": "向下滑动", "value": "down"}, {"label": "向左滑动", "value": "left"}, {"label": "向右滑动", "value": "right"}], "default": "up", "dynamics": [{"key": "$this.direction.show", "expression": "return $this.mode.value == ''direction''"}], "required": true}, {"types": "PhoneElement", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "element", "title": "区域元素", "name": "element", "tip": "滑动区域选择指定元素时传入元素对象", "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.element.show", "expression": "return $this.area.value == ''element''"}], "required": true}, {"types": "SwipeAreaType", "formType": {"type": "RADIO"}, "key": "area", "title": "滑动区域", "name": "area", "tip": "在整个屏幕中/在指定元素中", "options": [{"label": "在整个屏幕中", "value": "screen"}, {"label": "在指定元素中", "value": "element"}], "default": "screen", "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "sx", "title": "起始点横坐标", "name": "sx", "tip": "坐标模式下起始点X", "default": 0, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.sx.show", "expression": "return $this.mode.value == ''coord''"}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "sy", "title": "起始点纵坐标", "name": "sy", "tip": "坐标模式下起始点Y", "default": 0, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.sy.show", "expression": "return $this.mode.value == ''coord''"}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "ex", "title": "结束点横坐标", "name": "ex", "tip": "坐标模式下结束点X", "default": 0, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.ex.show", "expression": "return $this.mode.value == ''coord''"}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "ey", "title": "结束点纵坐标", "name": "ey", "tip": "坐标模式下结束点Y", "default": 0, "value": [{"type": "str", "value": ""}], "dynamics": [{"key": "$this.ey.show", "expression": "return $this.mode.value == ''coord''"}], "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "duration", "title": "滑动时间(毫秒)", "name": "duration", "tip": "用于调整滑动速度", "default": 300, "value": [{"type": "str", "value": ""}], "required": true}, {"types": "Float", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "after_delay", "title": "执行后延迟(秒)", "name": "after_delay", "tip": "指令执行完成后的等待时间", "default": 0.5, "value": [{"type": "str", "value": ""}], "required": true}], "outputList": [], "icon": "phone-swipe", "helpManual": "模拟人工滑动手机屏幕; 滑动方式支持按方向(上/下/左/右)或按坐标(起始点到结束点); 滑动区域可选整个屏幕或指定元素内"}',NULL,'2026-08-16 13:54:07','2026-08-16 13:54:07');
INSERT INTO `c_atom_meta_new` (`id`,`atom_key`,`atom_content`,`sort`,`create_time`,`update_time`)  VALUES ('910','Phone.wait_element','{"key": "Phone.wait_element", "title": "等待元素(手机)", "version": "1.0.0", "src": "astronverse.phone.phone.Phone().wait_element", "comment": "等待元素出现/消失，结果保存至(@{result})", "inputList": [{"types": "PhoneObject", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "conn", "title": "手机连接对象", "name": "conn", "tip": "选择通过【连接手机】创建的连接对象", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "PhoneElement", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "element", "title": "元素对象", "name": "element", "tip": "通过【获取手机元素对象】获取", "value": [{"type": "str", "value": ""}], "required": true}, {"types": "WaitType", "formType": {"type": "RADIO"}, "key": "wait_type", "title": "等待方式", "name": "wait_type", "tip": "等待目标元素出现/消失", "options": [{"label": "出现", "value": "appear"}, {"label": "消失", "value": "disappear"}], "default": "appear", "required": true}, {"types": "Int", "formType": {"type": "INPUT_VARIABLE_PYTHON"}, "key": "timeout", "title": "超时时间(秒)", "name": "timeout", "tip": "超时后流程自动继续执行", "default": 20, "value": [{"type": "str", "value": ""}], "required": true}], "outputList": [{"types": "Bool", "formType": {"type": "RESULT"}, "key": "result", "title": "等待结果保存至", "tip": "超时时间内状态符合为True, 否则False"}], "icon": "phone-wait-element", "helpManual": "等待手机元素出现或消失再继续执行; 超时后自动继续, 返回True/False"}',NULL,'2026-08-16 13:54:07','2026-08-16 13:54:07');
